async function runDesignsystemBalance(browser, baseUrl) {
    const seed = createBalanceStorage(2025);
    const storage = { ...seed, ...createBrowserProfileStorage({
        'design-a': { name: 'Synthetisches Profil A – ' + 'Langer vollständiger Profilname '.repeat(10), tagesgeld: '10000', balanceStateRaw: seed[BALANCE_STATE_KEY] },
        'design-b': { name: 'Muster A', tagesgeld: '20000', balanceStateRaw: seed[BALANCE_STATE_KEY] }
    }, 'design-a') };
    storage[EXPENSES_KEY] = JSON.stringify({ version: 1, activeYear: 2025, years: {
        '2025': { months: { '1': { profiles: { 'design-a': { categories: { Nullimport: 0 }, updatedAt: '2025-01-31T12:00:00Z' } } } } },
        '2026': { months: {} }
    } });
    const smoke = await openSmokePage(browser, baseUrl, 'Balance.html', { storage, observeWealthUpdates: true });
    const { page } = smoke;
    try {
        const keys = ['fixedIncomeAnnual', 'tagesgeld', 'geldmarktEtf', 'depotwertGesamt', 'goldWert', 'costBasisAlt', 'costBasisNeu', 'goldCost'];
        await page.waitForFunction(() => document.getElementById('tagesgeld').dataset.fieldState === 'adopted');
        // Lesende Rendererproben in den echten Diagrammflächen; keine Fixturewrites.
        const chartFixture = createDesignsystemDataLayoutFixture();
        for (const width of [1920, 2560]) {
            await page.setViewportSize({ width, height: 900 });
            for (const count of [2, 24]) {
                const kind = 'expenses';
                await activateSuiteSection(page, 'expenses');
                const measured = await page.evaluate(async ({ count, expenses }) => {
                    const dom = { isVisible: () => true, chart: document.getElementById('expensesHistoryChart'),
                        table: document.getElementById('expensesHistoryTable'), hint: document.getElementById('expensesHistoryHint') };
                    // VS-3a: Der alte Balance-Verlaufsrenderer ist entfernt; gemessen wird der Ausgabenverlauf.
                    const { renderBalanceExpensesHistory } = await import('./app/balance/balance-expenses-history-renderer.js');
                    renderBalanceExpensesHistory(dom, { status: 'ok', store: { ...expenses,
                        years: Object.fromEntries(Object.entries(expenses.years).slice(-count)) } }, 2026);
                    await document.fonts.ready;
                    // Die Diagrammfläche zeichnet nach ihrer Größenmessung; auf das tatsächliche SVG warten.
                    for (let frame = 0; !dom.chart.querySelector('svg') && frame < 120; frame++) await new Promise(resolve => requestAnimationFrame(resolve));
                    const svg = dom.chart.querySelector('svg'), box = svg.getBoundingClientRect(), viewBox = svg.viewBox.baseVal;
                    const scales = [...svg.querySelectorAll('text')].map(node => {
                        const matrix = node.getScreenCTM();
                        return [Math.hypot(matrix.a, matrix.b), Math.hypot(matrix.c, matrix.d)];
                    });
                    const live = [dom.hint].map(node => {
                        const css = getComputedStyle(node);
                        return { empty: node.textContent === '', hidden: node.hidden, display: css.display,
                            visibility: css.visibility, margin: css.margin };
                    });
                    return { scales, live, width: box.width, height: box.height,
                        ratio: viewBox.width / viewBox.height, minWidth: Number.parseFloat(svg.style.minWidth) };
                }, { kind, count, expenses: JSON.parse(chartFixture.storage[EXPENSES_KEY]) });
                assert(measured.scales.length > 0 && measured.scales.every(([x, y]) => x > 0 && Math.abs(x - y) < 1e-6),
                    `${width}/${count}/${kind}: Schrift hat gleichen x/y-Maßstab`);
                assert(Math.abs(measured.width / measured.height - measured.ratio) < 0.01 && measured.width >= measured.minWidth - 1,
                    `${width}/${count}/${kind}: automatische Höhe und datenabhängige Mindestbreite bleiben erhalten`);
                assert(measured.live.every(region => region.empty && !region.hidden && region.display !== 'none'
                    && region.visibility === 'visible' && region.margin === '0px'),
                `${width}/${count}/${kind}: leere Live-Regionen bleiben ohne Absatzabstand vorhanden`);
            }
        }
        await activateSuiteSection(page, 'overview');
        const checkOrigins = async () => {
            await activateSuiteSection(page, 'strategy');
            const rows = await page.evaluate(() => ['income', 'cash', 'money-market', 'depot', 'gold-bonds', 'costs'].map(key => {
                const row = document.getElementById(`balanceAdopt-${key}`), css = getComputedStyle(row);
                return { state: row.dataset.fieldState, opacity: css.opacity,
                    source: document.getElementById(row.getAttribute('aria-describedby'))?.textContent || '' };
            }));
            assert(rows.every(row => row.state === 'adopted' && row.opacity === '1' && row.source.startsWith('Aus ')),
                'Übernommene Einkünfte, Bestände und Einstandswerte haben Herkunft an den heutigen Anzeigekacheln');
            assert(await page.evaluate(keys => keys.every(id => document.getElementById(id).disabled), keys),
                'Die zugehörigen Vertragsbrücken bleiben gesperrt');
            assert(await page.locator('#renteAktiv, #renteMonatlich').evaluateAll(fields => fields.every(field =>
                field.type === 'hidden' && !field.hasAttribute('data-field-state'))), 'Verborgene Rentenbrücke erhält keine neue Darstellung');
        };
        await checkOrigins();
        await openBalanceHouseholdList(page);
        for (const width of [1920, 2560]) {
            await page.setViewportSize({ width, height: 900 });
            await assertProfilverbundGeometry(page, ['Synthetisches Profil A – ' + 'Langer vollständiger Profilname '.repeat(10), 'Muster A'], width);
        }
        const invariant = await page.evaluate(async keys => {
            const { renderProfileInputOrigins } = await import('./app/balance/balance-main-profile-sync.js');
            const inputs = Object.fromEntries(keys.map(id => [id, document.getElementById(id)]));
            const snapshot = () => keys.map(id => { const f = inputs[id]; return [f.value, f.disabled, f.readOnly, f.title, f.type, f.getAttribute('inputmode')]; });
            const before = snapshot(); renderProfileInputOrigins({ inputs }, true);
            return JSON.stringify(before) === JSON.stringify(snapshot());
        }, keys);
        assert(invariant, 'Reine Darstellung erhält Werte, Sperren und alte Inputattribute im echten DOM');
        const before = await page.locator('#tagesgeld').inputValue();
        // AP-1: B verlässt den Haushalt durch Löschen; A rechnet danach allein.
        await deleteBrowserPerson(page, 'design-b');
        await page.waitForFunction(before => document.getElementById('tagesgeld').value !== before, before);
        await checkOrigins();
        await activateSuiteSection(page, 'strategy');
        // Inventar B20: Einstandswerte liegen als Vertragsbrücken hinter der lesenden Herkunftskachel.
        const einstand = await page.locator('#costBasisAlt').evaluate(field => ({
            bridgeHidden: document.getElementById('balanceContractInputs')?.hidden === true && field.closest('#balanceContractInputs') !== null,
            rendered: field.getClientRects().length > 0, disabled: field.disabled,
            reason: document.getElementById('balanceAdopt-costs-source')?.textContent || ''
        }));
        assert(einstand.bridgeHidden && !einstand.rendered && einstand.disabled && einstand.reason.includes('Aus den Tranchen im Vermögen'),
            'Einstandsherkunft steht an der Anzeigekachel; die verborgene Vertragsbrücke bleibt gesperrt');
        // B2: Nullimport, Vorschau und Löschung am tatsächlichen Ausgabenhost.
        await page.goto(`${baseUrl}/Ausgaben.html?year=2025#ausgaben`); await waitExpensesBrowser(page);
        const cell = month => page.locator(`#expensesTable [data-month="${month}"][data-profile="design-a"]`);
        const total = month => page.locator(`#expensesTable [data-month-total="${month}"] [data-role="total"]`);
        assert((await cell(1).locator('[data-role="value"]').textContent()).includes('0'), 'Gespeicherter Nullimport erscheint als echte Null');
        assert(await total(2).textContent() === '—' && await total(2).evaluate(node => !['budget-ok', 'budget-warn', 'budget-bad'].some(name => node.classList.contains(name))), 'Datenloser Monat bleibt neutral');
        await cell(1).locator('[data-action="details"]').click();
        const del = page.locator('#expensesDetailDelete');
        assert(await del.isVisible() && await del.getAttribute('tabindex') !== '-1', 'Nullimport bleibt löschbar und per Tastatur erreichbar');
        await page.locator('#expensesDetailClose').click();
        assert(await cell(2).locator('[data-action="details"]').isDisabled(), 'Datenloser Monat bleibt ohne Detailslöschung');
        const chooserPromise = page.waitForEvent('filechooser');
        await cell(2).locator('[data-action="import"]').click();
        await (await chooserPromise).setFiles({ name: 'synthetische-ausgaben.csv', mimeType: 'text/csv', buffer: Buffer.from('Kategorie;Betrag\nTest;-100') });
        // Seit Paket D5 zeigt der Import vor dem Speichern die Vorschau.
        await page.locator('#expensesImportPreview').waitFor();
        await page.locator('[data-expenses-preview-accept]').click();
        await total(2).filter({ hasText: '100' }).waitFor();
        await cell(2).locator('[data-action="details"]').click();
        await page.locator('#expensesDetailDialog').waitFor({ state: 'visible' });
        assert((await page.locator('#expensesDetailBody').textContent()).includes('Test'), 'Detailsaktion behält Erreichbarkeit und Inhalt');
        await page.locator('#expensesDetailClose').click();
        if (!await page.locator('#expensesDetailDialog').isVisible()) await cell(2).locator('[data-action="details"]').click();
        await page.locator('#expensesDetailDelete').click();
        await answerPageDialog(page, { action: 'escape', label: 'Monatsdaten löschen' });
        assert((await total(2).textContent()).includes('100'), 'Escape erhält importierte Monatsdaten');
        if (!await page.locator('#expensesDetailDialog').isVisible()) await cell(2).locator('[data-action="details"]').click();
        await page.locator('#expensesDetailDelete').click();
        await answerPageDialog(page, { label: 'Monatsdaten löschen' });
        await total(2).filter({ hasText: '—' }).waitFor();
        await page.locator('#expensesYearSegments [data-balance-year="2026"]').click();
        assert(await page.locator('#expensesForecast').textContent() === '—'
            && await page.locator('#expensesForecast').evaluate(node => !['budget-ok', 'budget-warn', 'budget-bad'].some(name => node.classList.contains(name))), 'Leerjahr nach Jahreswechsel bleibt neutral');
        await activateSuiteSection(page, 'overview');
        await page.evaluate(async () => {
            const { createAnnualCloseDialog: createAnnualModalHandlers } = await import('./app/shared/annual-close-dialog.js');
            createAnnualModalHandlers({ getLastUpdateResults: () => null }).showUpdateResultModal({
                startTime: 0, endTime: 1000, age: { old: 67, new: 68 },
                cape: { capeRatio: 25, capeFetchStatus: 'warn_stale_source', sourceLabel: 'Synthetische Quelle' },
                errors: [{ step: 'Inflation', error: 'Synthetischer Jahresfehler' }]
            });
        });
        await page.locator('#balanceAnnualClose').waitFor({ state: 'visible' });
        assert((await page.locator('#annualResults .ds-note-warning').textContent()).includes('Quelle veraltet'), 'Jahreswarnung bleibt begründet');
        assert((await page.locator('#annualResults .ds-note-error').textContent()).includes('Synthetischer Jahresfehler'), 'Jahresfehler bleibt begründet');
        await page.locator('#balanceAnnualClose [data-close-dialog-close]').click();
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

export function createDesignsystemDataLayoutFixture() {
    const names = {
        'layout-a': 'Synthetisches Profil A – ' + 'Vollständiger Auswahlname '.repeat(10),
        'layout-b': 'Synthetisches Profil B – ' + 'Anderer langer Auswahlname '.repeat(10)
    };
    const seed = createBalanceStorage(2026), state = JSON.parse(seed[BALANCE_STATE_KEY]);
    state.wealthHistory = { schemaVersion: 1, entries: Array.from({ length: 24 }, (_, i) => ({
        id: `manual:2026-01-${String(i + 1).padStart(2, '0')}`, asOf: `2026-01-${String(i + 1).padStart(2, '0')}`,
        reason: 'manual', periodId: null, tagesgeld: 1000 + i, geldmarktEtf: 2000,
        depotwertAlt: 3000, depotwertNeu: 4000, aktienEtf: 7000, total: 10000 + i
    })) };
    seed[BALANCE_STATE_KEY] = JSON.stringify(state);
    seed[EXPENSES_KEY] = JSON.stringify({ version: 1, activeYear: 2026, years: Object.fromEntries(
        Array.from({ length: 24 }, (_, i) => [String(2003 + i), { months: { '1': { profiles: {
            'layout-a': { categories: { Test: -100 } }, 'layout-b': { categories: { Test: -50 } }
        } } } }])) });
    const lots = Array.from({ length: 10 }, (_, i) => createBrowserTranche({ trancheId: `layout-lot-${i}`,
        name: i === 0 ? 'Synthetische Tranche ' + 'Langer vollständiger Name '.repeat(12) : `Synthetische Tranche ${i}` }));
    const storage = { ...seed, depot_tranchen: JSON.stringify(lots), ...createBrowserProfileStorage(
        Object.fromEntries(Object.entries(names).map(([id, name]) => [id, { name, tagesgeld: '100000',
            balanceStateRaw: seed[BALANCE_STATE_KEY], tranchesRaw: JSON.stringify(lots) }])), 'layout-a') };
    return { storage, names, lots, state };
}

async function runDesignsystemDataLayout(browser, baseUrl) {
    const { storage, names, lots, state } = createDesignsystemDataLayoutFixture();
    const smoke = await openSmokePage(browser, baseUrl, 'index.html', { storage, observeWealthUpdates: true });
    const { page } = smoke;
    const noPageOverflow = async label => {
        const layout = await page.evaluate(() => ({ page: document.documentElement.scrollWidth, width: document.documentElement.clientWidth }));
        assert(layout.page <= layout.width + 1, `${label}: kein seitenweiter Überlauf (${JSON.stringify(layout)})`);
    };
    const fulltext = async selector => {
        const result = await page.locator(selector).evaluate(select => {
            const text = document.getElementById(`${select.id}-fulltext`), style = getComputedStyle(text), box = text.getBoundingClientRect();
            return { expected: select.selectedOptions[0]?.textContent, actual: text.textContent,
                wrap: style.overflowWrap, whiteSpace: style.whiteSpace, visible: box.height > 0,
                right: box.right, width: innerWidth, described: select.getAttribute('aria-describedby') };
        });
        assert(result.expected === result.actual && result.actual.length > 0 && result.visible
            && result.wrap === 'anywhere' && result.whiteSpace === 'normal' && result.right <= result.width + 1,
        `${selector}: ausgewählter Volltext ist sichtbar, vollständig und umbrechend`);
        assert(result.described.includes(`${selector.slice(1)}-fulltext`), 'Auswahlvolltext ergänzt die zugängliche Beschreibung');
    };
    const scrollByKeyboard = async selector => {
        const region = page.locator(selector);
        await region.evaluate(node => { node.scrollLeft = 0; });
        let dimensions = await region.evaluate(node => ({ client: node.clientWidth, scroll: node.scrollWidth }));
        // Umbrechende Inhalte können bei breiten Fenstern vollständig hineinpassen. Dann wird der Bereich für die
        // Tastaturprobe vorübergehend schmal gemacht; geprüft wird die interne Scrollbarkeit, nicht die Textbreite.
        const constrained = dimensions.scroll <= dimensions.client;
        if (constrained) {
            await region.evaluate(node => { node.dataset.smokeMaxWidth = node.style.maxWidth; node.style.maxWidth = '240px'; });
            dimensions = await region.evaluate(node => ({ client: node.clientWidth, scroll: node.scrollWidth }));
        }
        assert(dimensions.scroll > dimensions.client, `${selector}: gefüllte Daten benötigen die interne Scrollfläche`);
        await region.focus();
        await region.press('ArrowRight');
        await page.waitForFunction(selector => document.querySelector(selector).scrollLeft > 0, selector);
        assert(await region.evaluate(node => document.activeElement === node), `${selector}: Tastaturfokus bleibt beim Scrollen erhalten`);
        if (constrained) await region.evaluate(node => { node.style.maxWidth = node.dataset.smokeMaxWidth || ''; delete node.dataset.smokeMaxWidth; node.scrollLeft = 0; });
    };
    try {
        for (const width of [1280, 1366, 1920, 2560]) {
            await page.setViewportSize({ width, height: 900 });
            await page.locator('#overviewPeople').filter({ hasText: names['layout-a'] }).waitFor();
            assert((await page.locator('#overviewPeople').textContent()).includes(names['layout-b']), 'Übersicht erhält beide vollständigen Personennamen');
            await noPageOverflow(`Übersicht ${width}`);
        }
        await page.locator('.suite-navigation a[href="depot-tranchen-manager.html"]').click();
        await page.waitForURL('**/depot-tranchen-manager.html');
        await measureProfileSwitchBoundary(page, 'vor Wechsel');
        await switchBrowserProfile(page, 'layout-b', { returnToOverview: false });
        assert(await page.locator('#managerSectionNav [data-manager-profile="layout-b"]').evaluate(node => document.activeElement === node), 'Profilwechsel erhält Rückfokus am aktiven Managerreiter');
        const beforeReload = await measureProfileSwitchBoundary(page, 'Erfolg vor sofortigem Reload');
        // Der Managerreiter liest den Namen getrimmt aus seinem Textknoten; der Fixturename endet mit Leerzeichen.
        assert(beforeReload.selection === 'layout-b' && beforeReload.current === 'layout-b'
            && beforeReload.fulltext === names['layout-b'].trim(), 'Darstellung und aktuelle Profil-ID bestätigen B unabhängig voneinander');
        assert(beforeReload.backend.every(id => id === 'layout-b'), 'Erfolg bestätigt beide Profil-IDs im IndexedDB-Backend');
        await page.evaluate(() => history.replaceState(null, '', '?person=layout-b#managerDepotTitle'));
        await page.reload({ waitUntil: 'load' });
        await page.waitForFunction(() => document.querySelector('#managerSectionNav [aria-selected="true"]')?.dataset.managerProfile === 'layout-b');
        const afterReload = await measureProfileSwitchBoundary(page, 'nach Reload');
        assert(afterReload.selection === 'layout-b' && afterReload.current === 'layout-b'
            && afterReload.fulltext === names['layout-b'].trim() && afterReload.backend.every(id => id === 'layout-b'),
        'Reload mit ausdrücklichem Personenziel erhält B in Reiter, vollständigem Namen, aktueller ID und beiden Backend-IDs');
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.locator('#tranchenTable table').waitFor();
        // Die Depottabelle enthält zusätzlich Gruppenkopf- und Verlaufszeilen; gezählt werden die Bestandszeilen.
        assert(await page.locator('#tranchenTable tbody tr.tranche-row').count() === lots.length, 'Manager zeigt alle synthetischen Bestandszeilen');
        await assertCurrentSelectionText(page, await page.locator('select[id]').evaluateAll(nodes => nodes.map(node => node.id)));
        assert(await page.locator('#tranchenTable tbody tr.tranche-row td').nth(3).evaluate(node => getComputedStyle(node).fontVariantNumeric.includes('tabular-nums')), 'Manager-Zahlspalten sind tabellarisch');
        // FR-79: Der geführte Verkauf nennt die Tranche in Klartext; Öffnen und Schließen ohne Eingaben schreibt nichts.
        // VN-1 Punkt 2: Bei mehreren Tranchen steht zuerst die Wahl, ohne Vorwahl.
        await page.locator('#depotOpenSaleEntryBtn').click();
        await page.locator('#saleFlowDialog [data-sale-flow-tranche-choice]').waitFor();
        await page.locator('#saleFlowDialog [data-close-dialog-close]').click();
        await page.locator('#saleFlowDialog').waitFor({ state: 'detached' });
        for (const width of [1280, 1366, 1920, 2560]) {
            await page.setViewportSize({ width, height: 900 });
            await noPageOverflow(`Manager ${width}`);
            await scrollByKeyboard('#tranchenTable .table-scroll');
            assert(await page.locator('#tranchenTable .ds-scroll-hint').isVisible(), 'Manager zeigt die Fortsetzung sichtbar an');
        }
        await openManagerCards(page);
        const managerSelectionFixtures = async () => {
            const ids = ['profileHealthBucketTargetMode', 'profileHealthBucketAssetSource'];
            // Tabellenbereitschaft bestätigt nicht den Adapterwrite des Subpage-Bootstraps.
            await page.waitForFunction(() => window.__rsProfileSubpageLifecycleInitialized === true);
            await page.evaluate(async () => {
                const { isInitialized, flush } = await import('./app/shared/persistence-facade.js');
                if (!isInitialized()) throw new Error('Managerpersistenz ist noch nicht initialisiert');
                await flush();
            });
            await assertCurrentSelectionText(page, ids, true);
            const before = (await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value;
            await page.evaluate(ids => {
                window.__managerSelectionFixtureEvents = ids.map(id => {
                    const select = document.getElementById(id), counts = { input: 0, change: 0 };
                    const handler = event => { counts[event.type]++; };
                    for (const type of ['input', 'change']) select.addEventListener(type, handler);
                    return { id, select, counts, handler };
                });
            }, ids);
            try {
                for (const width of [1280, 1366, 1920, 2560]) {
                    await page.setViewportSize({ width, height: 900 });
                    for (const id of ids) {
                        const baseline = await page.locator(`#${id}`).evaluate(select => ({ value: select.value, disabled: select.disabled }));
                        await page.locator(`#${id}`).evaluate(select => { select.selectedOptions[0].textContent = 'Langer synthetischer Manager-Volltext '.repeat(12); });
                        await page.locator(`#${id}-fulltext`).filter({ hasText: 'Langer synthetischer' }).waitFor({ state: 'visible' });
                        await fulltext(`#${id}`);
                        await page.locator(`#${id}`).evaluate(select => { select.selectedOptions[0].textContent = 'Kurz'; });
                        await page.waitForFunction(id => { const text = document.getElementById(`${id}-fulltext`); return text?.textContent === 'Kurz' && text.hidden; }, id);
                        await assertCurrentSelectionText(page, [id], true);
                        assert(await page.locator(`#${id}`).evaluate((select, baseline) => select.value === baseline.value && select.disabled === baseline.disabled, baseline),
                            `${id}: Textfixture erhält Wert und Sperre`);
                    }
                    await noPageOverflow(`Managerauswahlen ${width}`);
                }
                // Auch versehentlich während der Fixtures eingereihte Writes müssen sichtbar werden.
                await page.evaluate(async () => (await import('./app/shared/persistence-facade.js')).flush());
                const counts = await page.evaluate(() => window.__managerSelectionFixtureEvents.map(({ id, counts }) => ({ id, ...counts })));
                for (const count of counts) assert(count.input === 0 && count.change === 0,
                    `${count.id}: reine Managertextfixtures erzeugen keine input-/change-Ereignisse`);
                assert((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value === before, 'Reine Managertextfixtures ändern keine Persistenz einschließlich updatedAt');
            } finally {
                await page.evaluate(() => {
                    for (const { select, handler } of window.__managerSelectionFixtureEvents || []) {
                        for (const type of ['input', 'change']) select.removeEventListener(type, handler);
                    }
                    delete window.__managerSelectionFixtureEvents;
                });
            }
        };
        await managerSelectionFixtures();
        await openTrancheCreate(page);
        await assertCurrentSelectionText(page, ['category', 'type'], true);
        await page.locator('#trancheForm').evaluate(form => form.reset());
        await assertCurrentSelectionText(page, ['category', 'type'], true);
        await page.keyboard.press('Escape');
        await page.reload({ waitUntil: 'load' });
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.locator('#tranchenTable table').waitFor();
        await assertCurrentSelectionText(page, await page.locator('select[id]').evaluateAll(nodes => nodes.map(node => node.id)));
        // Karten beginnen nach dem Reload wieder geschlossen.
        await openManagerCards(page);
        await managerSelectionFixtures(); // Nichtpersistente Textfixture bewusst erneut setzen.

        // Profilname und Kennung bleiben interne Metadaten.
        const managerProfileText = (await page.locator('#suiteProfileContext').getAttribute('data-profile-name')).replace(/\s+/g, ' ').trim();
        assert(managerProfileText === names['layout-b'].replace(/\s+/g, ' ').trim() && await page.locator('#suiteProfileContext').getAttribute('data-profile-id') === 'layout-b', 'Manager behält den aktiven Profilbezug nach Reload');
        await page.goto(`${baseUrl}/Balance.html`, { waitUntil: 'load' });
        // Beide Haushaltsprofile behalten positive Bedarfe und ausreichend zuordenbares Tagesgeld.
        await waitBalanceHouseholdList(page);
        const coverageValue = page.locator('#balanceReserveCoverage');
        await coverageValue.waitFor();
        for (const width of [1280, 1366, 1920, 2560]) {
            await page.setViewportSize({ width, height: 900 });
            await activateSuiteSection(page, 'overview');
            await noPageOverflow(`Balance inaktiv ${width}`);
            assert(await page.locator('#wealthHistoryChart svg').count() === 0
                && await page.locator('#expensesHistoryChart, #expensesHistoryTable').count() === 0, 'Inaktive Balance erzeugt keine Wealth-Details und enthält keine Ausgabenhosts');
            const coverage = await coverageValue.textContent();
            assert(/heute [\d.,]+\u00a0% gedeckt/.test(coverage),
                'Reservebalken zeigt die aktuelle Deckung mit deutscher Zahlendarstellung und U+00A0');
            await activateSuiteSection(page, 'expenses');
            await page.locator('#expensesTable table').waitFor();
            assert(await page.locator('#expensesTable tbody tr').count() === 12, 'Ausgabenmatrix enthält die bestehenden zwölf Monatszeilen');
            await noPageOverflow(`Ausgabenmatrix ${width}`);
            // Lange Profilköpfe dürfen im Container umbrechen oder intern scrollen.
            const matrix = await expensesMonthlyRegion(page);
            if (await matrix.evaluate(node => node.scrollWidth > node.clientWidth)) await scrollByKeyboard('.expenses-table-region[aria-label="Monatsausgaben"]');
            await activateSuiteSection(page, 'overview');
            await activateSuiteSection(page, 'expenses');
            await assertExpensesBrowserRegions(page);
            assert(await page.locator('#expensesHistoryTable tbody tr').count() === 24, 'Ausgabenverlauf enthält alle gespeicherten synthetischen Jahre');
            await assertExpensesBrowserTable(page, JSON.parse(storage[EXPENSES_KEY]), await page.evaluate(() => new Date().getFullYear()));
            assert(!(await page.locator('#expensesHistoryChart svg').innerHTML()).match(/NaN|Infinity/), 'Ausgabenverlauf hat endliche SVG-Koordinaten');
            for (const [selector, expectedWidth] of [['#expensesHistoryChart svg', 3710]]) {
                await activateSuiteSection(page, selector.startsWith('#expenses') ? 'expenses' : 'history');
                // Die Diagrammfläche zeichnet nach dem Sichtbarwerden neu; gemessen wird erst das über zwei Frames stabile SVG.
                await page.waitForFunction(selector => {
                    const node = document.querySelector(selector);
                    if (!node) return false;
                    const key = `${node.getBoundingClientRect().width}|${node.viewBox.baseVal.width}`, last = window.__smokeChartStable;
                    window.__smokeChartStable = { node, key };
                    return last?.node === node && last.key === key;
                }, selector, { polling: 'raf' });
                assert(await page.locator(selector).evaluate((node, minimum) =>
                    node.viewBox.baseVal.width >= minimum
                    && Math.abs(node.getBoundingClientRect().width - node.viewBox.baseVal.width) < 1
                    // Subpixelrauschen der Layoutengine (z. B. 360,00006 px) ist keine Maßabweichung.
                    && Math.abs(node.getBoundingClientRect().height - (node.parentElement.id === 'wealthHistoryChart' ? 360 : 270)) < 0.01, expectedWidth),
                    `${selector}: Pixelmaße erhalten alle 24 Records`);
            }
            await noPageOverflow(`Ausgaben Jahresdiagramm ${width}`);
            for (const selector of ['#expensesHistoryChart']) {
                await activateSuiteSection(page, selector.startsWith('#expenses') ? 'expenses' : 'history');
                await scrollByKeyboard(selector);
            }
            const yearTable = page.locator('#expensesHistoryTable');
            if (await yearTable.evaluate(node => node.scrollWidth > node.clientWidth)) await scrollByKeyboard('#expensesHistoryTable');
            await noPageOverflow(`Ausgaben Jahreswerte ${width}`);
        }
        await activateSuiteSection(page, 'expenses');
        const expensesOrder = await page.evaluate(() => ['expensesTable', 'expensesHistoryChart', 'expensesHistoryTable']
            .map(id => document.getElementById(id)).every((node, i, nodes) => Boolean(node) && (i === 0 || Boolean(nodes[i - 1].compareDocumentPosition(node) & Node.DOCUMENT_POSITION_FOLLOWING))));
        assert(expensesOrder, 'Ausgaben behält Monatsmatrix, Jahresdiagramm und Jahreswertetabelle in DOM-Reihenfolge');
        await activateSuiteSection(page, 'overview');
        await page.emulateMedia({ media: 'print' });
        assert(await page.locator('.form-column').isHidden() && await page.locator('.tab-buttons').isHidden()
            && await page.locator('#openDiagnosisBtn').isHidden(), 'Druck erhält die bisherigen Ausblendungen');
        assert(await page.locator('#print-footer').isVisible() && await page.locator('#actionDetailsDialog').isVisible() && await page.locator('#handlungsanweisung').isVisible(), 'Druck erhält Auswertung und Druckfuß');
        assert(await page.locator('#balanceReserveValues').isHidden(), 'Druck blendet die Reservekarte aus');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

// Beobachtung wird vor Produktinitialisierung installiert; die echten Export-/Flushfunktionen bleiben aktiv.
const SUITE_PAGES = ['Ausgaben.html', 'index.html', 'Balance.html', 'Simulator.html', 'depot-tranchen-manager.html', 'Handbuch.html', 'Daten-Sicherung.html'];
export async function waitForSimulatorOpening(page, pageName, options = {}) {
    if (pageName !== 'Simulator.html') return;
    // Synchrones Polling beendet auch den Fehlerpfad. Die Fehlerweitergabe
    // erfolgt separat und hängt nicht von der Behandlung geworfener Pollfehler ab.
    await page.waitForFunction(() => window.__simulatorOpeningBacktestDone === true
        || Boolean(window.__simulatorOpeningBacktestError), undefined, options);
    const failure = await page.evaluate(() => window.__simulatorOpeningBacktestError || '');
    if (failure) throw new Error(failure);
}

// Seit Paket S1 ist das automatische Öffnungsergebnis kein Verlustgrund: Die Handoffmatrix wechselt
// ohne Schutzdialog. Ein dennoch gemeldeter Backtest-Ergebnisgrund wäre eine Regression.
export async function confirmSimulatorOpeningNavigation(page, source) {
    if (source !== 'Simulator.html') return;
    assert(!await page.evaluate(async () => {
        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
        return getPageNavigationGuard().reasons().some(reason => reason.owner === 'simulator-backtest' && reason.result);
    }), 'Automatisches Öffnungsergebnis meldet keinen Ergebnisverlustgrund');
}

async function createSuiteProbe(browser, baseUrl, source, { disabled = false, viewport,
    storage = createBrowserProfileStorage({ 'suite-a': { name: 'Rahmenprofil', tranchesRaw: '[]' } }, 'suite-a') } = {}) {
    const smoke = await createPage(browser, `Suite frame ${source}`, { storage });
    const { page, context } = smoke;
    try {
        if (viewport) await page.setViewportSize(viewport);
        await context.addInitScript(({ disabled }) => {
            window.__suiteProbe = { steps: [], disabled, failure: '', hold: true, release: null };
        }, { disabled });
        await context.route('**/app/profile/profile-navigation.js', async route => {
            const response = await route.fetch();
            let code = await response.text();
            code = code.replace('exporter = exportProfilesBundleToWindowName,', `exporter = async () => {
                window.__suiteProbe.steps.push('export');
                if (window.__suiteProbe.failure === 'export') throw new Error('SYNTHETIC_EXPORT_FAILURE');
                return exportProfilesBundleToWindowName();
            },`);
            code = code.replace('flusher = PersistenceFacade.flush,', `flusher = async () => {
                const probe = window.__suiteProbe;
                probe.steps.push('flush');
                if (probe.failure === 'flush') throw new Error('SYNTHETIC_FLUSH_FAILURE');
                if (probe.hold) await new Promise(resolve => { probe.release = resolve; });
                const result = await PersistenceFacade.flush();
                probe.steps.push('flush-confirmed');
                return result;
            },`);
            code = code.replace("root.addEventListener('click', handler);", "if (!window.__suiteProbe.disabled) root.addEventListener('click', handler);");
            code = code.replace('win.location.href = href;', `window.__suiteProbe.steps.push('navigate');
                sessionStorage.setItem('__suiteHandoffEvidence', JSON.stringify(window.__suiteProbe.steps));
                win.location.href = href;`);
            await route.fulfill({ response, body: code });
        });
        await page.goto(`${baseUrl}/${source}`);
        await waitForSimulatorOpening(page, source);
        await page.evaluate(async () => {
            const navigation = await import('./app/profile/profile-navigation.js');
            await navigation.whenProfilePageReady(document);
        });
        let navigations = 0;
        // Nur Dokumentwechsel zählen: 'load' feuert bei jedem neuen Dokument (auch gleiche Seite),
        // nicht bei Kapitelsprüngen (#hash) im selben Dokument.
        page.on('load', () => { navigations++; });
        return { ...smoke, navigations: () => navigations };
    } catch (error) { await smoke.close(); throw error; }
}

async function assertSuitePending(smoke, source, expected) {
    const { page } = smoke;
    const steps = await page.evaluate(() => window.__suiteProbe.steps);
    assert(steps.join(',') === expected, `Handoffbeweis vor Freigabe: ${steps.join(',')} statt ${expected}`);
    assert(new URL(page.url()).pathname.endsWith(`/${source}`) && smoke.navigations() === 0, 'Offener Flush hält URL und Dokumentwechsel fest');
}

async function completeSuiteProbe(smoke, target, expected) {
    const { page } = smoke;
    const loaded = page.waitForEvent('domcontentloaded');
    await page.evaluate(() => window.__suiteProbe.release());
    await loaded;
    await page.waitForLoadState('load');
    await waitForSimulatorOpening(page, target);
    await page.evaluate(async () => (await import('./app/profile/profile-navigation.js')).whenProfilePageReady(document));
    assert(new URL(page.url()).pathname.endsWith(`/${target}`) && smoke.navigations() === 1, 'Genau ein bestätigter Dokumentwechsel zum echten Linkziel');
    const result = await page.evaluate(async () => {
        const { persistenceStorage } = await import('./app/shared/persistence-facade.js');
        return { steps: JSON.parse(sessionStorage.getItem('__suiteHandoffEvidence')), id: persistenceStorage.getItem('rs_active_profile') };
    });
    assert(result.steps.join(',') === `${expected},flush-confirmed,navigate`, 'Export-/Flushreihenfolge wird bis zum Wechsel nachgewiesen');
    assert(result.id === 'suite-a', 'Am Ziel kommt das synthetische aktive Profil an');
}

async function runSuiteFrameHandoff(browser, baseUrl) {
    for (const source of SUITE_PAGES) {
        const targets = SUITE_PAGES.map(target => ({ target, selector: `.suite-navigation a[href="${target}"]` }));
        targets.push({ target: 'index.html', selector: '.suite-brand' });
        if (source === 'index.html') targets.push(
            { target: 'Balance.html', selector: '.suite-navigation a[href="Balance.html"]' },
            { target: 'Simulator.html', selector: '.suite-navigation a[href="Simulator.html"]' },
            { target: 'depot-tranchen-manager.html', selector: '.overview-assets a[href="depot-tranchen-manager.html"]' });
        if (source === 'Balance.html') targets.push({ target: 'depot-tranchen-manager.html', selector: '#actionDetailsDialog a[href="depot-tranchen-manager.html"]', openDialog: true });
        for (const { target, selector, openDialog } of targets) {
            const smoke = await createSuiteProbe(browser, baseUrl, source);
            try {
                if (openDialog) await smoke.page.evaluate(() => document.getElementById('actionDetailsDialog').showModal());
                const link = smoke.page.locator(selector);
                assert(await link.count() === 1, `${source}: tatsächlich bedienbarer Einstieg ${selector}`);
                await link.focus(); await smoke.page.keyboard.press('Enter');
                await confirmSimulatorOpeningNavigation(smoke.page, source);
                await smoke.page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
                const expected = target === 'depot-tranchen-manager.html' ? 'flush' : 'export,flush';
                await assertSuitePending(smoke, source, expected);
                await link.evaluate(node => node.click());
                await assertSuitePending(smoke, source, expected);
                await completeSuiteProbe(smoke, target, expected);
                smoke.assertNoErrors();
            } finally { await smoke.context.close(); }
        }
    }
}

async function runSuiteFrameFailures(browser, baseUrl) {
    for (const source of SUITE_PAGES) {
        const smoke = await createSuiteProbe(browser, baseUrl, source);
        const { page } = smoke;
        try {
            for (const failure of ['export', 'flush']) {
                await page.evaluate(failure => { window.__suiteProbe.failure = failure; window.__suiteProbe.steps = []; }, failure);
                await page.locator('.suite-navigation a[href="Balance.html"]').evaluate(node => node.click());
                await confirmSimulatorOpeningNavigation(page, source);
                await page.waitForFunction(() => !document.getElementById('suiteNavigationStatus').hidden);
                assert(smoke.navigations() === 0, `${source}: ${failure} sperrt den Wechsel`);
                assert(await page.locator('#suiteNavigationStatus').textContent() !== '', `${source}: Fehler bleibt sichtbar`);
                await page.evaluate(() => { document.getElementById('suiteNavigationStatus').hidden = true; });
            }
            await page.evaluate(() => { window.__suiteProbe.failure = ''; window.__suiteProbe.steps = []; });
            const exceptions = await page.evaluate(() => {
                const sourceLink = document.querySelector('.suite-navigation a[href="Balance.html"]');
                const results = [];
                for (const special of [{ ctrlKey: true }, { metaKey: true }, { shiftKey: true }, { altKey: true }, { button: 1 }, { prevented: true }]) {
                    const event = new MouseEvent('click', { bubbles: true, cancelable: true, ...special });
                    if (special.prevented) event.preventDefault();
                    // Nach dem Produktbinder verhindern, damit die Gegenprobe kein natives Fenster öffnet.
                    const cancel = e => { results.push(e.defaultPrevented === Boolean(special.prevented)); e.preventDefault(); };
                    document.addEventListener('click', cancel, { once: true }); sourceLink.dispatchEvent(event);
                }
                for (const attrs of [{ href: '#suiteMain' }, { download: 'probe.html' }, { target: '_blank' }]) {
                    const link = sourceLink.cloneNode(true);
                    for (const [name, value] of Object.entries(attrs)) link.setAttribute(name, value);
                    sourceLink.parentNode.appendChild(link);
                    document.addEventListener('click', event => { results.push(!event.defaultPrevented); event.preventDefault(); }, { once: true });
                    link.click(); link.remove();
                }
                return { results, steps: window.__suiteProbe.steps };
            });
            assert(exceptions.results.every(Boolean) && exceptions.steps.length === 0, 'Modifikatoren, verhinderte Ereignisse, Download, Kapitel und fremder Tab bleiben ohne Handoff');
            await page.locator('.suite-navigation a[href="Handbuch.html"]').evaluate(node => node.click());
            await confirmSimulatorOpeningNavigation(page, source);
            await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
            await completeSuiteProbe(smoke, 'Handbuch.html', 'export,flush');
            assert(await page.locator('#suiteNavigationStatus').isHidden(), 'Expliziter erfolgreicher Wechsel hebt den Handofffehler auf');
            smoke.assertNoErrors();
        } finally { await smoke.context.close(); }
    }
}

function suiteProfileFixture() {
    const storage = createBrowserProfileStorage({
        'suite-a': { name: 'Synthetisch A', tagesgeld: '100000',
            tranchesRaw: JSON.stringify([createBrowserTranche({ name: 'Bestand A', trancheId: 'suite-lot-a' })]) },
        'suite-b': { name: 'Synthetisch B', tagesgeld: '200000',
            tranchesRaw: JSON.stringify([createBrowserTranche({ name: 'Bestand B', trancheId: 'suite-lot-b' })]) }
    }, 'suite-a');
    // AP-1: Beide Personen bilden den Haushalt. Fälle, die A löschen, rechnen danach mit B allein; dafür liegt
    // derselbe Plan schon als Einzelplan von B bereit, damit der Seitenstart keine Planumstellung braucht.
    const now = () => new Date('2026-07-14T00:00:00.000Z');
    const seeded = addDirectHouseholdPlans(storage, { now }).household_plan_v1;
    const values = Object.values(JSON.parse(seeded).entries)[0].values;
    storage[HOUSEHOLD_PLAN_KEY] = buildPlanRecord(seeded, [{ scope: planScope('single', ['suite-b']), values }], { now }).raw;
    return storage;
}

// H1: Ohne gespeicherte Bedarfe zeigte der Simulator bisher leere Bedarfsfelder (0/0); der gemeinsame Plan liefert
// jetzt 12.000/24.000. Mit Tagesgeld und Kleinsttranche endet ein Backtest dieser Fixture damit im schon vor H1
// vorhandenen technischen Fehler SIM_ENGINE_RESULT_SHAPE_INVALID (geplanter aktien_neu-Verkauf ohne Tranchenbestand)
// statt mit einem Ergebnis. Fälle, die nur einen echten Backtestbesitzer brauchen, behalten den bisherigen Bedarf 0/0.
function suiteProfileFixtureWithoutNeeds() {
    const storage = suiteProfileFixture();
    const values = { ...structuredClone(PLAN_DEFAULTS), floorBedarf: 0, flexBedarf: 0 };
    storage[HOUSEHOLD_PLAN_KEY] = buildPlanRecord(null, [{ scope: planScope('household', ['suite-a', 'suite-b']), values },
        { scope: planScope('single', ['suite-b']), values }], { now: () => new Date('2026-07-14T00:00:00.000Z') }).raw;
    return storage;
}

async function waitSuiteIdentity(page, id) {
    await page.waitForFunction(id => document.getElementById('suiteProfileContext')?.dataset.profileId === id, id);
    const state = await page.evaluate(async () => {
        const { persistenceStorage } = await import('./app/shared/persistence-facade.js');
        const registry = JSON.parse(persistenceStorage.getItem('rs_profiles_v1') || '{}');
        const entry = registry?.profiles?.[persistenceStorage.getItem('rs_current_profile')] ?? registry?.[persistenceStorage.getItem('rs_current_profile')];
        return { current: persistenceStorage.getItem('rs_current_profile'), active: persistenceStorage.getItem('rs_active_profile'),
            label: document.getElementById('suiteProfileContext').dataset.profileName, hidden: document.getElementById('suiteProfileContext').hidden, name: entry?.meta?.name ?? entry?.name ?? null };
    });
    assert(state.current === id && state.active === id, 'Kopfidentität stimmt mit beiden aktuellen Speicherkennungen überein');
    const expectedName = id === 'suite-a' ? 'Synthetisch A' : id === 'suite-b' ? 'Synthetisch B' : state.name;
    assert(expectedName && state.label === expectedName && state.hidden, 'Aktuelle Profilidentität bleibt intern erhalten und im Kopf verborgen');
}

async function acceptBacktestNavigation(page, link) {
    const destination = new URL(await link.getAttribute('href'), page.url());
    const downloaded = page.waitForEvent('download');
    await page.locator('#exportBacktestCsv').click();
    const download = await downloaded;
    assert(download.suggestedFilename().endsWith('.csv'), 'Echter Backtestexport erzeugt einen CSV-Download');
    assert(await page.evaluate(async () => {
        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
        return getPageNavigationGuard().reasons().some(reason => reason.owner === 'simulator-backtest' && reason.result);
    }), 'Erfolgreicher Backtestexport quittiert den tatsächlichen Ergebnisverlustgrund nicht');
    await link.click();
    await page.locator('#navigationGuardDialog[open]').waitFor();
    assert((await page.locator('#navigationGuardDescription').textContent()).includes('Backtest: Ergebnis geht verloren'),
        'Echtes Backtestergebnis wird vor Profilnavigation ausdrücklich als Verlust benannt');
    await page.locator('#navigationGuardLeave').click();
    await page.waitForURL(url => url.origin === destination.origin && url.pathname === destination.pathname);
    // Der Profil-Handoff darf Queryparameter ergänzen; das Linkziel bleibt maßgeblich.
}

async function navigateCleanly(page, link, target) {
    let prompts = 0;
    const listener = () => { prompts++; };
    page.on('dialog', listener);
    try {
        assert(await page.evaluate(async () => {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            return getPageNavigationGuard().reasons().length === 0;
        }), 'Sauberer App-Gegenweg hat keinen Verlust- oder Commitgrund');
        await page.evaluate(() => {
            window.__cleanNavigationPrompts = 0;
            sessionStorage.removeItem('__cleanNavigationProbe');
            new MutationObserver(records => {
                window.__cleanNavigationPrompts += records.filter(record => record.oldValue === null).length;
            }).observe(document.getElementById('navigationGuardDialog'), { attributes: true, attributeOldValue: true, attributeFilter: ['open'] });
            addEventListener('pagehide', () => sessionStorage.setItem('__cleanNavigationProbe', String(window.__cleanNavigationPrompts)), { once: true });
        });
        await link.click();
        await page.waitForURL(target);
        assert(await page.evaluate(() => sessionStorage.getItem('__cleanNavigationProbe')) === '0',
            'Sauberer App-Gegenweg öffnet bis zum Dokumentende keinen eigenen Verlustdialog');
        assert(prompts === 0, 'Sauberer App-Gegenweg zeigt keine native Nachfrage');
    } finally { page.off('dialog', listener); }
}

async function waitSuiteLayout(page, source, previousDocument = null) {
    await page.waitForURL(`**/${source}`);
    await page.waitForFunction(({ source, previousDocument }) => location.pathname.endsWith(`/${source}`)
        && document.readyState === 'complete' && window.__suiteDocumentId
        && window.__suiteDocumentId !== previousDocument
        && window.__suitePageshow?.id === window.__suiteDocumentId
        && document.getElementById('suiteProfileContext')?.dataset.profileId === 'suite-a'
        && document.getElementById('suiteSidebarToggle')?.disabled === false,
    { source, previousDocument });
    await waitSuiteIdentity(page, 'suite-a');
    return page.evaluate(async () => {
        const { whenProfilePageReady } = await import('./app/profile/profile-navigation.js');
        await whenProfilePageReady();
        await document.fonts.ready;
        await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
        return { id: window.__suiteDocumentId, pageshow: window.__suitePageshow, path: location.pathname };
    });
}

async function runSuiteFrameProfileContext(browser, baseUrl) {
    for (const source of SUITE_PAGES) {
        const smoke = await createPage(browser, 'Suite frame profile context', { storage: suiteProfileFixture() });
        const { page } = smoke;
        try {
            const calculator = ['Balance.html', 'Simulator.html'].includes(source);
            // PH-1: Haushalt im Manager vorbereiten, bevor die Rechenseite startet.
            // Der Kontextfall verlässt dadurch keinen unbedienten Rechenlauf per goto.
            await page.goto(`${baseUrl}/${calculator ? 'depot-tranchen-manager.html' : source}`);
            await waitSuiteIdentity(page, 'suite-a');
            if (calculator) {
                await deleteBrowserPerson(page, 'suite-a');
                await page.goto(`${baseUrl}/${source}`);
                await page.waitForFunction(pageName => document.getElementById('suiteHouseholdContext')?.textContent === (pageName === 'Balance.html' ? 'Berechnet für: Haushalt · Synthetisch B' : 'Haushalt: Synthetisch B'), source);
                // PH-1: Rückkehr in den Manager wählt das erste verbleibende Haushaltsmitglied (tranchen-manager-page.js).
                await waitSuiteIdentity(page, 'suite-b');
                assert(!JSON.parse((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value).profiles['suite-a'],
                    'Kopf übernimmt den Haushalt aus Personen verwalten');
            } else assert(await page.locator('#suiteHouseholdContext').count() === 0, 'Außerhalb Balance/Simulator bleibt Haushaltsanzeige verborgen');
            if (source === 'index.html') {
                await switchBrowserProfile(page, 'suite-b', { returnToOverview: false });
                assert((await page.locator('#suiteProfileContext').getAttribute('data-profile-name')).includes('Synthetisch B'), 'Manager und Kopf zeigen dieselbe Identität');
                await page.locator('#managePeopleBtn').click();
                await page.locator('[data-person-action="rename"][data-person-id="suite-b"]').click();
                await page.locator('#managerPersonName').fill('Umbenanntes B');
                await page.locator('#managerPersonRenameBtn').click();
                await page.waitForFunction(() => document.getElementById('suiteProfileContext')?.dataset.profileName === 'Umbenanntes B');
                // Der Kopf liest bereits die Registry; erst der Formularreset beendet den Verwaltungsauftrag.
                await page.waitForFunction(() => document.getElementById('managerPersonRenameBtn').hidden
                    && document.getElementById('managerPersonName').value === ''
                    && !document.getElementById('managePeopleBtn').disabled);
                await page.getByRole('button', { name: 'Personenverwaltung schließen', exact: true }).click();
                await page.locator('#managerPeopleModal').waitFor({ state: 'hidden' });
                assert(await page.evaluate(async () => {
                    const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
                    return getPageNavigationGuard(document).reasons().length === 0;
                }), 'Gespeichertes Umbenennen und Dialogschluss hinterlassen keinen Navigationsschutz');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
    for (const [storage, label] of [[{}, ''], [{ rs_profiles_v1: '{' }, 'Profil nicht verfügbar']]) {
        const smoke = await createPage(browser, 'Suite frame neutral handbook', { storage });
        try {
            await smoke.page.goto(`${baseUrl}/Handbuch.html`);
            await smoke.page.waitForFunction(label => document.getElementById('suiteProfileContext')?.textContent === label, label);
            assert(await smoke.page.evaluate(async () => {
                const { persistenceStorage } = await import('./app/shared/persistence-facade.js');
                const raw = persistenceStorage.getItem('rs_profiles_v1');
                return raw === null || raw === '{';
            }), 'Handbuchanzeige erzeugt oder repariert keine Registry');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

function suiteHistoryPageKind(source) {
    const kinds = { 'Balance.html': 'balance', 'Ausgaben.html': 'expenses', 'Simulator.html': 'simulator', 'depot-tranchen-manager.html': 'manager' };
    assert(Object.hasOwn(kinds, source), `Unbekannte Historienseite: ${source}`);
    return kinds[source];
}

function assertSuiteExpensesContent(shown, id) {
    const suffix = id === 'suite-a' ? 'A' : 'B';
    assert(JSON.stringify(shown.ids) === JSON.stringify(['', 'suite-a', 'suite-b'])
        && shown.selected.length === 1 && shown.selected[0] === id,
        'Ausgaben: aktueller Personenfilter statt fremder Einzelauswahl');
    assert(shown.context === `Berechnet für: Synthetisch ${suffix}` && shown.spent === UIUtils.formatBalanceCurrency(id === 'suite-a' ? 101 : 202)
        && shown.categories.includes(`Ausgabe ${suffix}`) && !shown.categories.includes(`Ausgabe ${suffix === 'A' ? 'B' : 'A'}`),
        'Ausgaben-Rückkehr zeigt eigene Personeninhalte statt alter A-Inhalte');
}

async function assertSuiteExpensesProfile(page, id) {
    await waitExpensesBrowser(page);
    await page.locator('#expensesYearSegments [data-balance-year="2026"]').click();
    await page.locator('#expensesPersonSegments [data-expenses-person=""]').click();
    assert((await page.locator('#expensesContext').textContent()) === 'Berechnet für: Haushalt · Synthetisch A + Synthetisch B'
        && (await page.locator('#expensesSpent').textContent()) === UIUtils.formatBalanceCurrency(303),
        'Ausgaben: Haushalt zeigt beide berechtigten Personen und ihre gemeinsamen Ausgaben');
    const person = page.locator(`#expensesPersonSegments [data-expenses-person="${id}"]`);
    assert(await person.count() === 1, 'Ausgaben: aktive Person besitzt genau ein Segment');
    await person.click();
    const shown = await page.evaluate(() => ({
        ids: [...document.querySelectorAll('#expensesPersonSegments [data-expenses-person]')].map(button => button.dataset.expensesPerson),
        selected: [...document.querySelectorAll('#expensesPersonSegments [aria-pressed="true"]')].map(button => button.dataset.expensesPerson),
        context: document.getElementById('expensesContext').textContent, spent: document.getElementById('expensesSpent').textContent,
        categories: document.getElementById('expensesCategories').textContent
    }));
    assertSuiteExpensesContent(shown, id);
}

async function runSuiteFrameProfileHistory(browser, baseUrl) {
    const profileABacktest = {};
    for (const source of ['Balance.html', 'Ausgaben.html', 'Simulator.html', 'depot-tranchen-manager.html']) {
        const storage = source === 'Simulator.html' ? suiteProfileFixtureWithoutNeeds() : suiteProfileFixture();
        const kind = suiteHistoryPageKind(source);
        if (kind === 'expenses') {
            // Beide Personen sind Haushaltsmitglieder; Einzelfilter prüfen eigene Ausgaben,
            // ohne einen echten Handoff nachträglich zu reparieren.
            storage[EXPENSES_KEY] = JSON.stringify({ version: 1, activeYear: 2026, years: { 2026: { months: { 1: { profiles: {
                'suite-a': { categories: { 'Ausgabe A': -101 } }, 'suite-b': { categories: { 'Ausgabe B': -202 } }
            } } } } } });
        }
        const smoke = await createPage(browser, 'Suite frame profile history', { storage, observeWealthUpdates: true, ...(kind === 'expenses' ? { fixedTime: '2026-10-10T12:00:00Z' } : {}) });
        const { page } = smoke;
        try {
            await page.goto(`${baseUrl}/${source}`);
            await waitSuiteIdentity(page, 'suite-a');
            if (source === 'Simulator.html') {
                await page.locator('.tab-btn[data-tab="backtesting"]').click();
                const start = await page.locator('#simStartJahr').evaluate(node => Number(node.min));
                await page.locator('#simStartJahr').fill(String(start));
                await page.locator('#simEndJahr').fill(String(start + 1));
                await page.locator('#btButton').click();
                await page.waitForFunction(() => ['completed', 'ruin'].includes(document.getElementById('backtestStatus')?.dataset.status));
                assert(await page.locator('#simulationResults').isVisible(), 'Profil A besitzt vor dem Wechsel echte sichtbare Backtestergebnisse');
                Object.assign(profileABacktest, await page.evaluate(() => ({ startJahr: window.globalBacktestData?.startJahr, years: window.globalBacktestData?.requestedYears })));
            } else if (source === 'Balance.html') {
                await page.waitForFunction(() => document.getElementById('monatlicheEntnahme')?.textContent.trim());
                assert(await page.locator('#monatlicheEntnahme').isVisible(), 'Balance A zeigt berechnete Entnahme');
            } else if (kind === 'expenses') {
                await assertSuiteExpensesProfile(page, 'suite-a');
            } else if (kind === 'manager') {
                await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
                await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
                await page.locator('.tranche-row').filter({ hasText: 'Bestand A' }).waitFor();
            }
            const home = page.locator('.suite-navigation a[href="index.html"]');
            if (source === 'Simulator.html') await acceptBacktestNavigation(page, home);
            else await navigateCleanly(page, home, '**/index.html');
            await page.waitForURL('**/index.html');
            await waitForWealthBrowserIdle(page);
            if (kind === 'expenses') await switchBrowserProfile(page, 'suite-b');
            else {
                // Der heutige Manager öffnet ohne Sprungziel das erste Haushaltsmitglied.
                // A deshalb vor dem B-Seitenstart auf derselben Managerseite löschen; B rechnet danach allein.
                await switchBrowserProfile(page, 'suite-b', { returnToOverview: false });
                await deleteBrowserPerson(page, 'suite-a', { stayInManager: true });
                await page.locator('.suite-navigation a[href="index.html"]').click();
                await page.waitForURL('**/index.html');
            }
            await waitForWealthBrowserIdle(page);
            await page.locator(`.suite-navigation a[href="${source}"]`).click();
            await page.waitForURL(`**/${source}`);
            await waitSuiteIdentity(page, 'suite-b');
            const verifyB = async () => {
                await waitSuiteIdentity(page, 'suite-b');
                if (source === 'Simulator.html') {
                    await page.waitForFunction(() => Number(document.getElementById('tagesgeld')?.value.replace(/\./g, '').replace(',', '.')) === 200000);
                    // Der Öffnungsbacktest rechnet sofort für B; sichtbar darf nur dieses eigene B-Ergebnis sein.
                    await waitForSimulatorOpening(page, 'Simulator.html');
                    await page.locator('.tab-btn[data-tab="backtesting"]').click();
                    const shown = await page.evaluate(() => ({ persons: (window.globalBacktestData?.personDataContext?.persons || []).map(person => person.profileId),
                        startJahr: window.globalBacktestData?.startJahr, years: window.globalBacktestData?.requestedYears,
                        tableRows: document.querySelectorAll('#simulationLog table tbody tr').length, rows: window.globalBacktestData?.rows?.length }));
                    assert(shown.persons.length > 0 && shown.persons.every(id => id === 'suite-b') && !(shown.startJahr === profileABacktest.startJahr && shown.years === profileABacktest.years),
                        'Nach Profilwechsel/Rückkehr wird der alte A-Backtest nicht als aktuelles B-Ergebnis gezeigt');
                    assert(shown.tableRows === 0 || shown.tableRows === shown.rows, 'Alte A-Ergebnistabelle bleibt auch im DOM aus');
                } else if (source === 'Balance.html') {
                    await page.waitForFunction(() => Number(document.getElementById('tagesgeld')?.value.replace(/\./g, '').replace(',', '.')) === 200000);
                    await waitForWealthBrowserIdle(page);
                    await page.waitForFunction(() => window.__profilverbundProfileSummaries?.length === 1 && window.__profilverbundProfileSummaries[0].profileId === 'suite-b');
                    const result = await page.evaluate(() => ({ label: document.getElementById('suiteHouseholdContext').textContent,
                        cash: document.getElementById('tagesgeld').value, result: document.getElementById('monatlicheEntnahme').textContent }));
                    assert(result.label === 'Berechnet für: Haushalt · Synthetisch B' && result.result.trim(), 'Balance-Rückkehr berechnet sichtbare Ergebnisse aus aktuellem Haushalt B');
                } else if (kind === 'expenses') {
                    await assertSuiteExpensesProfile(page, 'suite-b');
                } else if (kind === 'manager') {
                    await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
                    await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
                    await page.locator('.tranche-row').filter({ hasText: 'Bestand B' }).waitFor();
                    assert(await page.locator('.tranche-row').filter({ hasText: 'Bestand A' }).count() === 0, 'Manager-Rückkehr zeigt ausschließlich aktuellen Bestand B');
                }
            };
            await verifyB();
            // Neuer Profilstand besitzt kein Ergebnis: auch der saubere App-Weg
            // wird vor der bestehenden Historienprüfung wirklich durchlaufen.
            await navigateCleanly(page, page.locator('.suite-navigation a[href="index.html"]'), '**/index.html');
            await page.locator(`.suite-navigation a[href="${source}"]`).click();
            await page.waitForURL(`**/${source}`); await verifyB();
            await page.goBack(); await page.waitForURL('**/index.html');
            await page.goBack(); await page.waitForURL(`**/${source}`); await verifyB();
            await page.goForward(); await page.waitForURL('**/index.html');
            await page.goForward(); await page.waitForURL(`**/${source}`); await verifyB();
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runSuiteFrameBfcache(browser, baseUrl) {
    await runNavigationGuardFrozenBfcache(browser, baseUrl);
    const smoke = await createPage(browser, 'Suite frame bfcache', { storage: suiteProfileFixture(), observeWealthUpdates: true });
    const { page, context } = smoke;
    await context.addInitScript(() => addEventListener('pageshow', event => {
        const observations = JSON.parse(sessionStorage.getItem('__suitePageshow') || '[]');
        observations.push({ path: location.pathname, persisted: event.persisted });
        sessionStorage.setItem('__suitePageshow', JSON.stringify(observations));
    }));
    try {
        await page.goto(`${baseUrl}/depot-tranchen-manager.html`);
        await waitSuiteIdentity(page, 'suite-a');
        await page.locator('.suite-navigation a[href="index.html"]').click();
        await page.waitForURL('**/index.html');
        await waitForWealthBrowserIdle(page);
        await switchBrowserProfile(page, 'suite-b', { returnToOverview: false });
        await deleteBrowserPerson(page, 'suite-a', { stayInManager: true });
        await page.goBack();
        await page.waitForURL('**/index.html');
        await waitSuiteIdentity(page, 'suite-b');
        await waitForWealthBrowserIdle(page);
        await page.goBack();
        await page.waitForURL('**/depot-tranchen-manager.html');
        await waitSuiteIdentity(page, 'suite-b');
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.locator('.tranche-row').filter({ hasText: 'Bestand B' }).waitFor();
        assert(await page.locator('.tranche-row').filter({ hasText: 'Bestand A' }).count() === 0, 'Historienrückkehr zeigt keine A-Bestandszeile');
        const observations = await page.evaluate(() => JSON.parse(sessionStorage.getItem('__suitePageshow') || '[]'));
        const restored = observations.findIndex(row => row.persisted === true && row.path.endsWith('depot-tranchen-manager.html'));
        if (restored >= 0) {
            assert(observations.slice(restored + 1).some(row => row.path.endsWith('depot-tranchen-manager.html') && row.persisted === false), 'Real beobachtete BFCache-Rückkehr löst einen neuen Seitenstart aus');
            console.log('Suite frame bfcache SOURCE: persisted === true beobachtet; Reload und Identität B geprüft.');
        } else console.log('Suite frame bfcache SOURCE: persisted === true nicht beobachtet; reguläre Historienrückkehr geprüft, kein BFCache-Erfolgsbeleg.');
        smoke.assertNoErrors();
        return { bfcacheObserved: restored >= 0 };
    } finally { await smoke.close(); }
}

async function runSuiteFrameWidths(browser, baseUrl) {
    for (const source of SUITE_PAGES) {
        const smoke = await createPage(browser, 'Suite frame widths', { storage: suiteProfileFixture() });
        const { page, context } = smoke;
        await context.addInitScript(() => {
            const original = Storage.prototype.setItem;
            window.__suiteDocumentId = crypto.randomUUID();
            window.__suitePageshow = null;
            addEventListener('pageshow', event => { window.__suitePageshow = { persisted: event.persisted, id: window.__suiteDocumentId }; });
            window.__suitePreferenceWrites = 0;
            Storage.prototype.setItem = function(key, value) {
                if (key === 'ui_suite_sidebar_collapsed') window.__suitePreferenceWrites++;
                return original.call(this, key, value);
            };
        });
        const measure = () => page.evaluate(async () => {
            await document.fonts.ready;
            await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
            const shell = document.querySelector('.suite-shell'), content = document.querySelector('.suite-content');
            return { viewport: innerWidth, page: document.documentElement.scrollWidth, shell: shell.getBoundingClientRect().width,
                content: content.getBoundingClientRect().width, rem: parseFloat(getComputedStyle(document.documentElement).fontSize),
                columns: getComputedStyle(document.querySelector('.suite-layout')).gridTemplateColumns,
                writes: window.__suitePreferenceWrites };
        });
        // Der Simulator-Öffnungsbacktest hinterlässt einen echten Ergebnisgrund; Layoutbedienung darf keinen weiteren erzeugen.
        const guardReasons = () => page.evaluate(async () => {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            return JSON.stringify(getPageNavigationGuard().reasons().map(({ owner, dirty, result, message }) => ({ owner, dirty, result, message })));
        });
        try {
            await page.goto(`${baseUrl}/${source}`);
            const documentBefore = await waitSuiteLayout(page, source);
            await waitForSimulatorOpening(page, source);
            // Nach dem Öffnungsbacktest speichert der Simulator das Ergebnis noch kurz („wird gespeichert“); erst danach vergleichen.
            let reasonsBefore = await guardReasons();
            for (let tries = 0; tries < 60 && JSON.parse(reasonsBefore).some(reason => String(reason.message).includes('wird gespeichert')); tries++) {
                await page.waitForTimeout(250); reasonsBefore = await guardReasons();
            }
            assert(JSON.parse(reasonsBefore).every(reason => source === 'Simulator.html' && reason.owner === 'simulator-backtest' && reason.result && !reason.dirty),
                `${source}: vor der Breitenbedienung besteht höchstens der Ergebnisgrund des Öffnungsbacktests`);
            for (const width of [1366, 1920, 2560]) {
                await page.setViewportSize({ width, height: 900 });
                await page.waitForFunction(() => !document.getElementById('suiteSidebarToggle').disabled);
                const full = await measure();
                assert(full.page <= full.viewport + 1 && full.shell >= 82 * full.rem, `${source}/${width}: voller Rahmen hält das äußere Breitenbudget`);
                assert(full.writes === 0, 'Laden und Resize speichern keine Präferenz');
                if (source === 'Balance.html' && width === 1366) assert(await page.locator('.main-layout').evaluate(node => getComputedStyle(node).flexDirection) === 'column', 'Volle Leiste bei 1366px lässt Balance unter seine 1250px-Inhaltsgrenze fallen');
                await page.locator('#suiteSidebarToggle').focus(); await page.keyboard.press('Enter');
                const compact = await measure();
                console.log('Suite frame widths SOURCE ' + JSON.stringify({ source, width, full, compact }));
                assert(Math.abs(compact.content - full.content - 8 * full.rem) <= 1, 'Symbolleiste gibt genau acht Rem Inhaltsbreite zurück');
                if (source === 'Balance.html' && width === 1366) assert(await page.locator('.main-layout').evaluate(node => getComputedStyle(node).flexDirection) === 'row', 'Kompakte Leiste überschreitet im selben 1366px-Fenster die Balance-Inhaltsgrenze');
                assert(await page.locator('#suiteSidebarToggle').getAttribute('aria-expanded') === 'false', 'Tastaturaktion aktualisiert zugänglichen Zustand');
                await page.locator('#suiteSidebarToggle').click();
                // Zähler nur für den nächsten Resizevergleich zurücksetzen, Storage bleibt unverändert.
                await page.evaluate(() => { window.__suitePreferenceWrites = 0; });
            }
            // BF-1 / GEMEINSAM §11: keine künstlich auf unter 1280 px verengten Rahmen oder Inhalte.
            await page.locator('#suiteSidebarToggle').click();
            assert(await guardReasons() === reasonsBefore, 'Breiten-/Layoutbedienung erzeugt keinen falschen Navigationsgrund');
            await page.reload();
            const documentAfter = await waitSuiteLayout(page, source, documentBefore.id);
            assert(documentAfter.id !== documentBefore.id && documentAfter.pageshow?.persisted === false,
                'Breitenmessung nach Reload beobachtet ein neues bereites Dokument statt einer BFCache-Ansicht');
            console.log('Suite frame widths SOURCE ' + JSON.stringify({ source, documentBefore, documentAfter }));
            assert(await page.locator('#suiteSidebarToggle').getAttribute('aria-expanded') === 'false', 'Reload übernimmt die manuelle Gerätepräferenz');
            await waitForSimulatorOpening(page, source);
            const resultReason = JSON.parse(await guardReasons()).length > 0;
            await page.locator('.suite-brand').focus(); await page.keyboard.press('Enter');
            if (resultReason) {
                // Der erneute Öffnungsbacktest ist ein echtes Ergebnis; sein Verlust wird wie vom Benutzer bestätigt.
                await page.locator('#navigationGuardDialog[open]').waitFor();
                assert((await page.locator('#navigationGuardDescription').textContent()).includes('Backtest: Ergebnis geht verloren'),
                    'Markennavigation benennt den echten Backtest-Ergebnisverlust');
                await page.locator('#navigationGuardLeave').click();
            }
            // Von index.html aus passt die URL schon vor der Navigation; auf das neue Dokument warten.
            await waitSuiteLayout(page, 'index.html', documentAfter.id);
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
    // Fehlgeschlagenes Gerätespeichern darf die bestehende Profilübergabe nicht blockieren.
    const smoke = await createPage(browser, 'Suite frame preference failure', { storage: suiteProfileFixture() });
    try {
        await smoke.context.addInitScript(() => {
            const original = Storage.prototype.setItem;
            Storage.prototype.setItem = function(key, value) {
                if (key === 'ui_suite_sidebar_collapsed') throw new Error('SYNTHETIC_DEVICE_WRITE_FAILURE');
                return original.call(this, key, value);
            };
        });
        await smoke.page.goto(`${baseUrl}/index.html`);
        await waitSuiteIdentity(smoke.page, 'suite-a');
        await smoke.page.locator('#suiteSidebarToggle').click();
        await smoke.page.locator('.suite-navigation a[href="Handbuch.html"]').click();
        await smoke.page.waitForURL('**/Handbuch.html');
        await waitSuiteIdentity(smoke.page, 'suite-a');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

// Je Wartestelle im aktuellen Dokument initialisieren, auch nach echten Reloads.
async function initializeBrowserSmokeNavigationGuard(page) {
    await page.evaluate(async () => {
        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
        window.__browserSmokeNavigationGuard = getPageNavigationGuard(document, window);
    });
}

// Dialog und Guardentscheidung müssen gemeinsam beendet sein; Gründe dürfen bleiben.
export async function waitForNavigationDecisionSettled(page, options = {}) {
    await initializeBrowserSmokeNavigationGuard(page);
    await page.waitForFunction(() => {
        return document.getElementById('navigationGuardDialog')?.open === false
            && window.__browserSmokeNavigationGuard?.isBusy() === false;
    }, undefined, options);
}

async function waitForNavigationGuardManagerReady(page) {
    await page.waitForURL('**/depot-tranchen-manager.html', { waitUntil: 'load' });
    // Die Personenkachel wird erst am Ende des Managerstarts eingeblendet.
    await page.locator('#managerPersonPanel:not([hidden]) #depotAddTrancheBtn:enabled').waitFor();
    await waitForNavigationDecisionSettled(page);
}

async function runNavigationGuardWaitCounterprobe(browser, baseUrl) {
    const { errors } = await import('playwright');
    const smoke = await createSuiteProbe(browser, baseUrl, 'index.html');
    const { page } = smoke;
    try {
        // Startschreiber (z. B. Kursverlauf) halten kurz einen Commitgrund; währenddessen lehnt der Schutz
        // jede Rückfrage mit „bitte warten“ ab. Die Gegenprobe beginnt erst nach diesen Startwrites.
        await waitForPageCondition(page, async () => {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            return !getPageNavigationGuard(document, window).reasons().some(reason => reason.phase === 'commit');
        });
        await page.evaluate(async () => {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            const guard = getPageNavigationGuard(document, window);
            const registration = guard.register('synthetic-navigation-wait-result', {
                read: () => ({ phase: 'idle', result: true, revision: 1 })
            });
            const probe = window.__navigationWaitProbe = { guard, registration, release: null };
            probe.dialogDecision = guard.prepare();
        });
        await page.locator('#navigationGuardDialog[open]').waitFor();
        await page.locator('#navigationGuardStay').click();
        await waitForNavigationDecisionSettled(page);
        assert(await page.evaluate(async () => await window.__navigationWaitProbe.dialogDecision === null),
            'Bleiben beendet die echte Dialogentscheidung ohne Zustimmung');

        await page.evaluate(() => {
            const probe = window.__navigationWaitProbe;
            probe.heldDecision = probe.guard.prepare({
                decide: () => new Promise(resolve => { probe.release = resolve; })
            });
        });
        try {
            assert(await page.evaluate(() => document.getElementById('navigationGuardDialog')?.open === false),
                'Timeout-Gegenprobe beginnt mit vorhandenem geschlossenem Dialog');
            assert(await page.evaluate(() => window.__navigationWaitProbe.guard.isBusy() === true
                && typeof window.__navigationWaitProbe.release === 'function'),
            'Timeout-Gegenprobe hält eine echte beschäftigte Guardentscheidung');
            let timedOut = false;
            try { await waitForNavigationDecisionSettled(page, { timeout: 250 }); }
            catch (error) {
                // Import-/Seitenfehler sind kein Nachweis des Playwright-Timeouts.
                if (!(error instanceof errors.TimeoutError)) throw error;
                timedOut = true;
            }
            assert(timedOut, 'Die tatsächliche Wartehilfe läuft bei geschlossenem Dialog und beschäftigtem Guard in den Playwright-Timeout');
        } finally {
            await page.evaluate(async () => {
                const probe = window.__navigationWaitProbe;
                probe.release(false);
                await probe.heldDecision;
                probe.release = null;
            });
        }

        await waitForNavigationDecisionSettled(page, { timeout: 1000 });
        assert(await page.evaluate(() => {
            const probe = window.__navigationWaitProbe;
            return document.getElementById('navigationGuardDialog')?.open === false
                && window.__browserSmokeNavigationGuard === probe.guard
                && probe.guard.isBusy() === false
                && probe.guard.reasons().some(reason => reason.owner === 'synthetic-navigation-wait-result' && reason.result);
        }), 'Die Positivprobe endet erst nach Entscheidungsende und erhält den Ergebnisgrund');
        smoke.assertNoErrors();
    } finally {
        try {
            await page.evaluate(async () => {
                const probe = window.__navigationWaitProbe;
                if (!probe) return;
                probe.release?.(false);
                if (document.getElementById('navigationGuardDialog')?.open) document.getElementById('navigationGuardStay').click();
                await probe.heldDecision;
                await probe.dialogDecision;
                probe.registration.unregister();
                delete window.__navigationWaitProbe;
            });
        } finally { await smoke.close(); }
    }
}

// Echte Handler; nur Vorbereitung und MC-UI-Cleanup werden kontrolliert gehalten.
async function runNavigationGuardCalculations(browser, baseUrl) {
    const smoke = await createSuiteProbe(browser, baseUrl, 'Simulator.html', { storage: createNavigationCalculationFixture() });
    const { page } = smoke;
    try {
        await page.locator('.tab-btn[data-tab="montecarlo"]').click();
        await page.evaluate(() => {
            const values = { simStartVermoegen: 520000, depotwertGesamt: 500000, depotwertAlt: 500000,
                einstandAlt: 400000, tagesgeld: 20000, geldmarktEtf: 0, startFloorBedarf: 24000,
                startFlexBedarf: 6000, minimumFlexAnnual: 0, mcAnzahl: 2, mcDauer: 2,
                mcBlockSize: 1, mcSeed: 42, mcMethode: 'block', rngMode: 'per-run-seed',
                mcWorkerCount: 1, mcWorkerBudget: 50 };
            for (const [id, value] of Object.entries(values)) {
                const field = document.getElementById(id);
                if (!field) continue;
                field.value = String(value);
                field.dispatchEvent(new Event('input', { bubbles: true }));
                field.dispatchEvent(new Event('change', { bubbles: true }));
            }
            for (const id of ['mcCompareMode', 'useCapeSampling', 'dynamicFlex', 'goGoActive', 'pflegefallLogikAktivieren']) {
                const field = document.getElementById(id);
                if (field) { field.checked = false; field.dispatchEvent(new Event('change', { bubbles: true })); }
            }
        });
        await page.evaluate(async () => {
            const mc = await import('./app/simulator/simulator-monte-carlo.js');
            const { createMonteCarloUI } = await import('./app/simulator/monte-carlo-ui.js');
            const { prepareHistoricalDataOnce } = await import('./app/simulator/simulator-engine-helpers.js');
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            const guard = getPageNavigationGuard(document);
            // Der Öffnungsbacktest hinterlässt bereits einen eigenen Ergebnisgrund.
            const calculations = () => guard.reasons().filter(reason => reason.owner === 'simulator-monte-carlo');
            window.__calculationProbe = { guard, calculations, releases: {}, ended: [], holdCleanup: false };
            window.__startGuardedCalculations = () => {
                const probe = window.__calculationProbe;
                probe.releases = {}; probe.ended = [];
                const prepare = owner => async () => {
                    await new Promise(resolve => { probe.releases[owner] = resolve; });
                    prepareHistoricalDataOnce();
                };
                const ui = createMonteCarloUI();
                const finish = ui.finishProgress.bind(ui);
                ui.finishProgress = async options => {
                    await finish(options);
                    if (!options.completed && probe.holdCleanup) {
                        await new Promise(resolve => { probe.releases.cleanup = resolve; });
                    }
                };
                probe.mc = mc.runMonteCarlo({ createUI: () => ui, prepareHistoricalData: prepare('mc') })
                    .then(() => { probe.ended.push('mc'); window.__suiteProbe.steps.push('mc-ended'); });
            };
            window.__startGuardedCalculations();
        });
        await page.waitForFunction(() => Object.keys(window.__calculationProbe.releases).length === 1);
        const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
        await link.focus(); await page.keyboard.press('Enter');
        await page.locator('#navigationGuardDialog[open]').waitFor();
        await page.locator('#navigationGuardStay').click();
        await waitForNavigationDecisionSettled(page);
        assert(await page.evaluate(() => window.__calculationProbe.calculations().length === 1
            && window.__calculationProbe.calculations().every(reason => reason.phase === 'preparing')),
            'Bleiben lässt die echte Rechnung ungekündigt');
        assert(await link.evaluate(node => document.activeElement === node), 'Bleiben stellt Rahmenlinkfokus wieder her');
        await page.evaluate(() => window.__calculationProbe.releases.mc());
        await page.waitForFunction(() => window.__calculationProbe.ended.length === 1);
        // TD-2: Das Monte-Carlo-Ergebnis ist für die Sitzung gemerkt und meldet keinen Verlust mehr.
        assert(await page.evaluate(() => window.__calculationProbe.calculations().length === 0
            && sessionStorage.getItem('rs_simulator_mc_result_v1') !== null),
        'Das gemerkte Monte-Carlo-Ergebnis veröffentlicht keinen Ergebnisgrund');
        // Alle Ergebnisbesitzer gemeinsam, nach echten Handlerabschlüssen.
        await page.evaluate(async () => {
            document.getElementById('simStartJahr').value = '2000';
            document.getElementById('simEndJahr').value = '2001';
            const { runBacktestWithRuntimeProvenance } = await import('./app/simulator/simulator-backtest.js');
            await runBacktestWithRuntimeProvenance();
        });
        assert(await page.evaluate(() => window.__calculationProbe.guard.reasons().filter(reason => reason.result).length === 1
            && !window.__calculationProbe.guard.reasons().some(reason => reason.owner === 'simulator-monte-carlo')),
            'Der Backtest meldet sein Ergebnis, Monte Carlo ist gemerkt');
        await page.locator('.tab-btn[data-tab="backtesting"]').click();
        const backtestDownload = page.waitForEvent('download');
        await page.locator('#exportBacktestCsv').click(); await backtestDownload;
        await page.locator('.tab-btn[data-tab="montecarlo"]').click();
        const downloaded = page.waitForEvent('download');
        await page.locator('#exportMonteCarloRunJson').click(); await downloaded;
        await link.focus(); await page.keyboard.press('Enter');
        await page.locator('#navigationGuardDialog[open]').waitFor();
        assert((await page.locator('#navigationGuardDescription').textContent()).includes('Ergebnis geht verloren – trotzdem wechseln?'),
            'Enter am Rahmenlink fragt nach MC-Export weiter nach dem Verlust der übrigen Ergebnisse');
        const combinedDescription = await page.locator('#navigationGuardDescription').textContent();
        assert((combinedDescription.match(/Ergebnis geht verloren/g) || []).length === 1
            && combinedDescription.includes('Backtest'),
            'Die Nachfrage nennt den nicht gemerkten Ergebnisgrund auch nach Downloads');
        await page.locator('#navigationGuardStay').click();
        await waitForNavigationDecisionSettled(page);
        assert(await page.evaluate(() => window.__calculationProbe.guard.reasons().every(reason => reason.result)),
            'Export und Bleiben quittieren kein weiter verfügbares Ergebnis');

        await page.evaluate(() => {
            window.__suiteProbe.steps = [];
            window.__calculationProbe.oldMcMemory = sessionStorage.getItem('rs_simulator_mc_result_v1');
            window.__calculationProbe.holdCleanup = true;
            window.__startGuardedCalculations();
        });
        await page.waitForFunction(() => Object.keys(window.__calculationProbe.releases).length === 1);
        await link.focus(); await page.keyboard.press('Enter');
        await page.locator('#navigationGuardDialog[open]').waitFor();
        await page.locator('#navigationGuardLeave').click();
        await page.waitForFunction(() => window.__calculationProbe.guard.reasons().filter(reason => reason.phase === 'cancelling').length === 1);
        assert(await page.evaluate(() => window.__suiteProbe.steps.length) === 0,
            'Akzeptierter Abbruch beginnt noch keinen Export oder Flush');
        await page.evaluate(() => window.__calculationProbe.releases.mc());
        await page.waitForFunction(() => !!window.__calculationProbe.releases.cleanup);
        await assertSuitePending(smoke, 'Simulator.html', '');
        assert(await page.evaluate(() => window.__calculationProbe.guard.reasons().filter(reason => reason.owner !== 'simulator-monte-carlo').every(reason => reason.result)
            && window.__calculationProbe.oldMcMemory !== null
            && sessionStorage.getItem('rs_simulator_mc_result_v1') === window.__calculationProbe.oldMcMemory),
            'Abgebrochener Folgelauf erhält das Backtest-Ergebnis und das gemerkte Monte-Carlo-Ergebnis');
        await page.evaluate(() => window.__calculationProbe.releases.cleanup());
        await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
        await assertSuitePending(smoke, 'Simulator.html', 'mc-ended,export,flush');
        await completeSuiteProbe(smoke, 'Handbuch.html', 'mc-ended,export,flush');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

async function runNavigationGuardBacktest(browser, baseUrl) {
    for (const rejectLoader of [false, true]) {
        const smoke = await createSuiteProbe(browser, baseUrl, 'Simulator.html');
        const { page } = smoke;
        try {
            await page.evaluate(async () => {
                const { runBacktestWithRuntimeProvenance, cancelBacktestPreparation } = await import('./app/simulator/simulator-backtest.js');
                const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
                const values = { simStartJahr: 2000, simEndJahr: 2001 };
                for (const [id, value] of Object.entries(values)) document.getElementById(id).value = String(value);
                // Das Ergebnis des Öffnungsbacktests ist der Ausgangsstand vor beiden Probeläufen.
                const probe = window.__backtestProbe = { guard: getPageNavigationGuard(document), ended: [], opening: window.globalBacktestData };
                probe.start = () => {
                    probe.ended = []; probe.loaderResolve = null;
                    probe.bt = runBacktestWithRuntimeProvenance({ loadRuntimeBuildProvenance: () => new Promise((resolve, reject) => {
                        probe.loaderResolve = resolve; probe.loaderReject = reject;
                    }) }).then(() => { probe.ended.push('bt'); });
                };
                probe.cancel = () => cancelBacktestPreparation();
                probe.start();
            });
            await page.waitForFunction(() => !!window.__backtestProbe.loaderResolve);
            const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
            await link.focus(); await page.keyboard.press('Enter');
            await page.locator('#navigationGuardStay').click();
            await waitForNavigationDecisionSettled(page);
            assert(await page.evaluate(() => window.__backtestProbe.guard.reasons().filter(reason => ['running', 'preparing'].includes(reason.phase)).length === 1),
                'Bleiben erhält die reale Backtestvorbereitung');
            // Eigener Abbruch, danach echter erneuter Start auf demselben Dokument.
            await page.evaluate(() => {
                const probe = window.__backtestProbe;
                probe.cancelled = probe.cancel();
                probe.loaderResolve(null);
            });
            await page.evaluate(() => window.__backtestProbe.cancelled);
            assert(await page.evaluate(() => window.globalBacktestData === window.__backtestProbe.opening),
                'Abgebrochener Erstlauf erzeugt kein verspätetes Ergebnis');
            await page.evaluate(() => window.__backtestProbe.start());
            await page.waitForFunction(() => !!window.__backtestProbe.loaderResolve);
            await page.evaluate(() => window.__backtestProbe.loaderResolve(null));
            await page.waitForFunction(() => window.__backtestProbe.ended.length === 1);
            assert(await page.evaluate(() => !!window.globalBacktestData?.result
                && window.globalBacktestData !== window.__backtestProbe.opening),
                'Erneuter Start veröffentlicht ein echtes Backtesthandler-Ergebnis');
            await page.evaluate(() => {
                const probe = window.__backtestProbe;
                probe.oldBT = window.globalBacktestData;
                probe.start(); window.__suiteProbe.steps = [];
            });
            await page.waitForFunction(() => !!window.__backtestProbe.loaderResolve);
            await link.focus(); await page.keyboard.press('Enter');
            await page.locator('#navigationGuardDialog[open]').waitFor();
            const description = await page.locator('#navigationGuardDescription').textContent();
            assert(description.includes('Backtest') && (description.match(/Ergebnis geht verloren/g) || []).length === 1,
                'Nachfrage nennt den laufenden Backtest und sein Altresultat');
            await page.locator('#navigationGuardLeave').click();
            await page.waitForFunction(() => window.__backtestProbe.guard.reasons().every(reason => reason.phase === 'cancelling'));
            await page.evaluate(rejectLoader => {
                const probe = window.__backtestProbe;
                if (rejectLoader) probe.loaderReject(new Error('Kontrollierter später Loaderfehler')); else probe.loaderResolve(null);
            }, rejectLoader);
            await page.waitForFunction(() => window.__backtestProbe.ended.includes('bt'));
            await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
            assert(await page.evaluate(() => window.globalBacktestData === window.__backtestProbe.oldBT
                && window.__backtestProbe.guard.reasons().every(reason => reason.phase === 'idle' && reason.result)),
                'Nach bestätigter Kündigung kein spätes Ergebnis; das alte Resultat bleibt erhalten');
            await completeSuiteProbe(smoke, 'Handbuch.html', 'export,flush');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

// Kontrollierte Provider prüfen den gemeinsamen Produktpfad, ohne Fachrechnungen.
async function installNavigationProbe(page, { running = false } = {}) {
    await page.evaluate(async ({ running }) => {
        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
        const guard = getPageNavigationGuard(document, window);
        window.__navigationProbe = { states: [], registrations: [], endings: [] };
        for (let index = 0; index < (running ? 2 : 1); index++) {
            const state = { result: true, phase: running ? 'running' : 'idle', revision: 1, operationId: `probe-${index}` };
            const registration = guard.register(`browser-probe-${index}`, { read: () => state, cancel: async () => {
                window.__suiteProbe.steps.push(`cancel-${index}`);
                await new Promise(resolve => { window.__navigationProbe.endings[index] = resolve; });
                state.phase = 'idle'; registration.notify();
                window.__suiteProbe.steps.push(`ended-${index}`);
                return true;
            } });
            window.__navigationProbe.states.push(state); window.__navigationProbe.registrations.push(registration);
        }
    }, { running });
}

async function measureNavigationGuardPresentation(page, label) {
    const dialog = page.locator('#navigationGuardDialog[open]');
    await dialog.waitFor({ state: 'visible' });
    assert(await dialog.evaluate(node => node.matches(':modal')), `${label}: echter modaler Top-Layer`);
    const measured = await page.evaluate(async label => {
        await document.fonts.ready;
        await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
        const dialog = document.getElementById('navigationGuardDialog');
        if (!dialog.matches(':modal')) throw new Error(`${label}: Top-Layer vor Messung verloren`);
        const canvas = document.createElement('canvas');
        canvas.width = canvas.height = 1;
        const context = canvas.getContext('2d');
        if (!context) throw new Error(`${label}: kein Canvas-2D-Kontext`);
        const alpha = color => {
            if (!CSS.supports('color', color)) throw new Error(`${label}: ungültige Messfarbe ${color}`);
            context.clearRect(0, 0, 1, 1);
            context.fillStyle = color;
            context.fillRect(0, 0, 1, 1);
            return context.getImageData(0, 0, 1, 1).data[3] / 255;
        };
        const box = dialog.getBoundingClientRect(), css = getComputedStyle(dialog);
        const backdropColor = getComputedStyle(dialog, '::backdrop').backgroundColor;
        const ancestors = [];
        for (let parent = dialog.parentElement; parent; parent = parent.parentElement) ancestors.push(parent);
        const nodes = [dialog, ...dialog.querySelectorAll('*'), ...ancestors];
        return {
            dx: Math.abs(box.x + box.width / 2 - innerWidth / 2),
            dy: Math.abs(box.y + box.height / 2 - innerHeight / 2),
            padding: [css.paddingTop, css.paddingRight, css.paddingBottom, css.paddingLeft].map(Number.parseFloat),
            backdropColor, backdropAlpha: alpha(backdropColor), surfaceAlpha: alpha(css.backgroundColor),
            reducedText: nodes.map(node => {
                const style = getComputedStyle(node);
                return { node: node.id || node.tagName, opacity: Number(style.opacity), color: style.color, alpha: alpha(style.color) };
            }).filter(node => node.opacity !== 1 || node.alpha !== 1)
        };
    }, label);
    const evidence = `${label}: ${JSON.stringify(measured)}`;
    assert(Number.isFinite(measured.dx) && measured.dx <= 2 && Number.isFinite(measured.dy) && measured.dy <= 2,
        `Dialogmittelpunkt höchstens 2 px je Achse – ${evidence}`);
    assert(measured.padding.every(value => Number.isFinite(value) && value >= 24), `Jedes Padding mindestens 24 px – ${evidence}`);
    assert(measured.backdropAlpha >= .3 && measured.backdropAlpha <= .6, `Canvas-Backdropalpha 0,3 bis 0,6 – ${evidence}`);
    assert(measured.surfaceAlpha === 1 && measured.reducedText.length === 0, `Opake Fläche und unverminderte Text-/Elterndeckkraft – ${evidence}`);
}

async function runNavigationGuardPresentation(browser, baseUrl) {
    let openings = 0;
    for (const width of [1366, 1920]) {
        for (const source of SUITE_PAGES) {
            const smoke = await createSuiteProbe(browser, baseUrl, source, { viewport: { width, height: 900 } });
            try {
                const { page } = smoke, target = source === 'Handbuch.html' ? 'index.html' : 'Handbuch.html';
                const input = 'Synthetische ungespeicherte Darstellungsprobe';
                if (source === 'depot-tranchen-manager.html') {
                    await page.locator('#managePeopleBtn').click();
                    await page.locator('#managerPersonName').fill(input);
                }
                await installNavigationProbe(page);
                await waitForNavigationDecisionSettled(page);
                const label = `${source} ${width}×900`;
                const targetLink = page.locator(`.suite-navigation a[href="${target}"]`);
                // Der Personendialog überdeckt den Rahmen für den Zeiger; der Tastaturweg zum Rahmenlink bleibt offen.
                if (source === 'depot-tranchen-manager.html') { await targetLink.focus(); await page.keyboard.press('Enter'); }
                else await targetLink.click();
                await measureNavigationGuardPresentation(page, `${label} navigate`); openings++;
                if (source === 'depot-tranchen-manager.html') assert(await page.locator('#managerPersonName').inputValue() === input, `${label}: Personenname während der Messung befüllt`);
                await page.locator('#navigationGuardStay').click();
                await waitForNavigationDecisionSettled(page);
                if (source === 'depot-tranchen-manager.html') assert(await page.locator('#managerPersonName').inputValue() === input, `${label}: Bleiben erhält Personenname`);

                // Die Entscheidung im Fenster halten, ohne page.evaluate bis zum Benutzerklick zu blockieren.
                await page.evaluate(async () => {
                    const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
                    window.__presentationCloseDecision = getPageNavigationGuard(document, window).prepare({ intent: 'close' });
                });
                await page.locator('#navigationGuardDialog[open]').waitFor({ state: 'visible' });
                assert(await page.getByRole('dialog', { name: 'Anwendung schließen?', exact: true }).count() === 1, `${label} close: gemeinsamer Schlusstitel`);
                assert(await page.locator('#navigationGuardLeave').textContent() === 'Trotzdem schließen', `${label} close: vorhandener Schlussknopf`);
                await measureNavigationGuardPresentation(page, `${label} close`); openings++;
                if (source === 'depot-tranchen-manager.html') assert(await page.locator('#managerPersonName').inputValue() === input, `${label} close: Personenname während der Messung befüllt`);
                await page.locator('#navigationGuardStay').click();
                await page.evaluate(async () => { await window.__presentationCloseDecision; });
                await waitForNavigationDecisionSettled(page);
                if (source === 'depot-tranchen-manager.html') assert(await page.locator('#managerPersonName').inputValue() === input, `${label} close: Bleiben erhält Personenname`);
                assert(await page.evaluate(() => window.__suiteProbe.steps.length) === 0 && smoke.navigations() === 0, `${label}: Bleiben ohne Handoff oder Seitenwechsel`);
                smoke.assertNoErrors();
            } finally { await smoke.close(); }
        }
        // Eigener Kontext ohne Verlustprovider: die echte Dirty-Schließstrecke ist der einzige Auslöser.
        const source = 'depot-tranchen-manager.html';
        const smoke = await createSuiteProbe(browser, baseUrl, source, { viewport: { width, height: 900 } });
        try {
            const { page } = smoke, label = `${source} ${width}×900 discard`, input = 'Ungespeicherte synthetische Tranche';
            await waitForNavigationGuardManagerReady(page);
            await openTrancheCreate(page);
            await page.locator('#name').fill(input);
            await page.locator('#closeTrancheModalBtn').click();
            await page.locator('#navigationGuardDialog[open]').waitFor({ state: 'visible' });
            assert(await page.getByRole('dialog', { name: 'Änderungen verwerfen?', exact: true }).count() === 1, `${label}: echter Verwerftitel`);
            assert(await page.locator('#trancheModal').evaluate(node => node.classList.contains('active')), `${label}: Fachdialog darunter weiter offen`);
            assert(await page.locator('#name').inputValue() === input, `${label}: Fachdialogeingabe während der Messung befüllt`);
            await measureNavigationGuardPresentation(page, label); openings++;
            await page.locator('#navigationGuardStay').click();
            await waitForNavigationDecisionSettled(page);
            assert(await page.locator('#trancheModal').evaluate(node => node.classList.contains('active'))
                && await page.locator('#name').inputValue() === input, `${label}: Bleiben erhält Fachdialog und Eingabe`);
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
    // Je Breite zwei Öffnungen pro Suite-Seite plus eine; seit Paket 14 gehört Daten-Sicherung.html dazu.
    const expectedOpenings = 2 * (SUITE_PAGES.length * 2 + 1);
    assert(openings === expectedOpenings, `Darstellungsmatrix vollständig: ${openings} von ${expectedOpenings} Öffnungen`);
}

async function runNavigationGuardLinks(browser, baseUrl) {
    for (const source of SUITE_PAGES) {
        const smoke = await createSuiteProbe(browser, baseUrl, source);
        try {
            const { page } = smoke, target = source === 'Handbuch.html' ? 'index.html' : 'Handbuch.html';
            await installNavigationProbe(page, { running: true });
            const link = page.locator(`.suite-navigation a[href="${target}"]`);
            await link.focus(); await page.keyboard.press('Enter');
            await page.locator('#navigationGuardDialog[open]').waitFor();
            assert(await page.evaluate(() => window.__suiteProbe.steps.length) === 0, 'Vor Zustimmung kein Abbruch/Export/Flush');
            await page.locator('#navigationGuardStay').click();
            await waitForNavigationDecisionSettled(page);
            assert(await page.evaluate(() => window.__suiteProbe.steps.length) === 0, 'Bleiben erhält Läufe und Ergebnis');
            assert(await link.evaluate(node => document.activeElement === node), 'Bleiben gibt Linkfokus zurück');
            await link.click(); await page.locator('#navigationGuardLeave').click();
            await page.waitForFunction(() => window.__navigationProbe.endings.filter(Boolean).length === 2);
            assert(await page.evaluate(() => window.__suiteProbe.steps.join(',')) === 'cancel-0,cancel-1', 'Alle Abbrüche vor Handoff angefordert');
            await page.evaluate(() => window.__navigationProbe.endings[1]());
            await page.waitForFunction(() => window.__suiteProbe.steps.includes('ended-1'));
            assert(!(await page.evaluate(() => window.__suiteProbe.steps)).includes('export'), 'Ein offenes Abbruchende verhindert Übergabe');
            await page.evaluate(() => window.__navigationProbe.endings[0]());
            await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
            const expected = 'cancel-0,cancel-1,ended-1,ended-0,export,flush';
            await assertSuitePending(smoke, source, expected);
            // Ein echter zweiter Linkklick während des Flush erzeugt keine Übergabe.
            await link.focus(); await page.keyboard.press('Enter');
            await assertSuitePending(smoke, source, expected);
            await completeSuiteProbe(smoke, target, expected);
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
    for (const [source, selector, target] of [
        ['index.html', '.overview-assets a[href="depot-tranchen-manager.html"]', 'depot-tranchen-manager.html'],
        ['depot-tranchen-manager.html', '#trancheRecoveryActions a[href="Daten-Sicherung.html#fullBackupImportBtn"]', 'Daten-Sicherung.html']
    ]) {
        const smoke = await createSuiteProbe(browser, baseUrl, source);
        try {
            const { page } = smoke;
            if (source.includes('manager')) await page.locator('#trancheRecoveryActions').evaluate(node => { node.hidden = false; const panel = node.closest('.persistence-panel'); if (panel) panel.hidden = false; });
            await installNavigationProbe(page);
            const link = page.locator(selector); await link.focus(); await page.keyboard.press('Enter');
            await page.locator('#navigationGuardDialog[open]').waitFor();
            await page.locator('#navigationGuardLeave').click();
            await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
            await assertSuitePending(smoke, source, 'flush');
            await completeSuiteProbe(smoke, target, 'flush');
            if (source.includes('manager')) await page.waitForFunction(() => location.hash === '#fullBackupImportBtn' && document.activeElement?.id === 'fullBackupImportBtn');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
    for (const stage of ['dialog', 'flush']) {
        const smoke = await createSuiteProbe(browser, baseUrl, 'index.html');
        try {
            const { page } = smoke; await installNavigationProbe(page);
            await page.evaluate(() => { window.name = 'previous channel'; });
            await page.locator('.suite-navigation a[href="Handbuch.html"]').click();
            await page.locator('#navigationGuardDialog[open]').waitFor();
            if (stage === 'flush') {
                await page.locator('#navigationGuardLeave').click();
                await page.waitForFunction(() => window.__suiteProbe.steps.includes('flush'));
            }
            await page.evaluate(() => { window.__navigationProbe.states[0].revision++; window.__navigationProbe.registrations[0].notify(); });
            if (stage === 'dialog') await page.locator('#navigationGuardLeave').click();
            else await page.evaluate(() => window.__suiteProbe.release());
            await page.locator('#suiteNavigationStatus').filter({ hasText: 'Zustand hat sich geändert' }).waitFor();
            assert(smoke.navigations() === 0 && await page.evaluate(() => window.name) === 'previous channel', 'Neue Revision verwirft Zustimmung/Übergabe ohne Zielwrite');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runNavigationGuardModal(browser, baseUrl) {
    const storage = createBrowserProfileStorage({ 'guard-modal': { name: 'Synthetischer Dialogtest', tranchesRaw: '[]' } }, 'guard-modal');
    const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', { storage });
    try {
        const { page } = smoke;
        await openTrancheCreate(page); await page.locator('#name').fill('Ungespeicherte Probe');
        await page.locator('#closeTrancheModalBtn').click();
        await page.locator('#navigationGuardDialog[open]').waitFor();
        assert(await page.getByRole('dialog', { name: 'Änderungen verwerfen?', exact: true }).count() === 1, 'Dirty-Schließen benennt Verwerfen im zugänglichen Dialognamen');
        assert(await page.locator('#navigationGuardLeave').textContent() === 'Verwerfen', 'Dirty-Schließen bestätigt Verwerfen');
        assert(await page.locator('#navigationGuardDescription').textContent() === 'Ungespeicherte Eingaben gehen verloren – trotzdem verwerfen?', 'Dirty-Schließen beschreibt den Eingabeverlust');
        assert(await page.evaluate(() => document.activeElement.id) === 'navigationGuardStay', 'Verlustdialog beginnt mit Bleiben');
        await page.keyboard.press('Shift+Tab');
        assert(await page.evaluate(() => document.activeElement.id) === 'navigationGuardLeave', 'Shift+Tab bleibt im obersten Dialog');
        await page.keyboard.press('Tab');
        assert(await page.evaluate(() => document.activeElement.id) === 'navigationGuardStay', 'Tab bleibt im obersten Dialog');
        assert(await page.locator('#navigationGuardDialog').evaluate(node => node.matches(':modal')), 'Hintergrund ist durch echten modalen Top-Layer gesperrt');
        await page.keyboard.press('Escape');
        await waitForNavigationDecisionSettled(page);
        assert(await page.locator('#trancheModal').evaluate(node => node.classList.contains('active')), 'Escape schließt keinen darunterliegenden Editor');
        assert(await page.locator('#name').inputValue() === 'Ungespeicherte Probe', 'Bleiben erhält echte Formularwerte');
        assert(await page.evaluate(() => document.activeElement.id) === 'closeTrancheModalBtn', 'Escape gibt Fokus an Schließauslöser zurück');
        await page.locator('#name').fill(''); await page.locator('#closeTrancheModalBtn').click();
        assert(await page.locator('#trancheModal').getAttribute('aria-hidden') === 'true', 'Rückänderung erlaubt Schließen ohne Nachfrage');
        await openTrancheCreate(page); await page.locator('#name').fill('Verwerfprobe');
        await page.locator('#closeTrancheModalBtn').click(); await page.locator('#navigationGuardLeave').click();
        assert(await page.locator('#trancheModal').getAttribute('aria-hidden') === 'true', 'Bestätigtes Verwerfen schließt Editor');
        assert((await readIndexedDb(page, 'kv', 'depot_tranchen')).value === '[]', 'Verwerfen schreibt keinen Bestand');
        await openTrancheCreate(page); await page.locator('#name').fill('Linkprobe nach Verwerfen');
        const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
        const box = await link.boundingBox();
        assert(box && box.width > 0 && box.height > 0, 'Rahmenziel besitzt echte Mauskoordinaten');
        let prompts = 0;
        await page.evaluate(() => {
            window.__modalNavigationPrompts = 0;
            new MutationObserver(records => {
                for (const record of records) if (record.attributeName === 'open' && record.oldValue === null)
                    window.__modalNavigationPrompts++;
            }).observe(document.getElementById('navigationGuardDialog'), { attributes: true, attributeOldValue: true, attributeFilter: ['open'] });
        });
        // TD-1h: Der größere Tranchendialog verdeckt die Navigation; ein Klick dort trifft den Dialog und bewirkt nichts.
        await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
        await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
        assert(page.url().endsWith('/depot-tranchen-manager.html') && await page.locator('#navigationGuardDialog').isHidden()
            && await page.locator('#trancheModal').getAttribute('aria-hidden') === 'false', 'Klick auf die verdeckte Navigation navigiert nicht und schließt nichts');
        // Echter Hintergrundpunkt: der Rand des Dialoghintergrunds außerhalb des Dialogfensters.
        const backdropPoint = await page.evaluate(() => {
            const modal = document.getElementById('trancheModal');
            for (const [x, y] of [[4, innerHeight - 4], [innerWidth - 4, innerHeight - 4], [4, 4], [innerWidth - 4, 4]]) {
                if (document.elementFromPoint(x, y) === modal) return { x, y };
            }
            return null;
        });
        assert(backdropPoint, 'Dialoghintergrund ist an einem Rand erreichbar');
        await page.mouse.click(backdropPoint.x, backdropPoint.y);
        await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
        assert(page.url().endsWith('/depot-tranchen-manager.html') && await page.locator('#navigationGuardDialog').isVisible(),
            'Vollständiger Hintergrundklick öffnet bei geänderten Angaben die Schutzfrage');
        assert(await page.evaluate(() => window.__modalNavigationPrompts) === 1, 'Hintergrundklick fragt genau einmal');
        assert(await page.locator('#navigationGuardTitle').textContent() === 'Änderungen verwerfen?', 'Hintergrundklick nutzt dieselbe Verwerfrückfrage wie Schließen');
        await page.keyboard.press('Escape');
        await waitForNavigationDecisionSettled(page);
        assert(await page.locator('#name').inputValue() === 'Linkprobe nach Verwerfen', 'Hintergrundversuch erhält Fachdialogwerte');
        await link.evaluate(node => node.click());
        await page.locator('#navigationGuardDialog[open]').waitFor();
        prompts = await page.evaluate(() => window.__modalNavigationPrompts);
        assert(prompts === 2, 'Programmatische App-Navigation fragt nach abgelehntem Hintergrundschließen erneut genau einmal');
        assert(await page.getByRole('dialog', { name: 'Seite verlassen?', exact: true }).count() === 1, 'Spätere Linknavigation stellt den zugänglichen Seitenwechseltitel wieder her');
        assert(await page.locator('#navigationGuardLeave').textContent() === 'Trotzdem wechseln', 'Spätere Linknavigation stellt den Wechselknopf wieder her');
        await page.keyboard.press('Escape');
        await waitForNavigationDecisionSettled(page);
        assert(page.url().endsWith('/depot-tranchen-manager.html'), 'Bleiben erhält die Managerseite');
        assert(await page.locator('#name').inputValue() === 'Linkprobe nach Verwerfen', 'Bleiben bei Linknavigation erhält die Eingaben');
        assert(await page.locator('#trancheModal').evaluate(node => node.classList.contains('active')), 'Escape erhält den darunterliegenden Fachdialog');
        assert(await page.evaluate(() => document.getElementById('trancheModal').contains(document.activeElement)),
            'Escape stellt bedienbaren Fokus im weiterhin offenen Fachdialog wieder her');
        await page.locator('#closeTrancheModalBtn').click(); await page.locator('#navigationGuardLeave').click();
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

