// SOURCE: isolierte Cashdialogfälle; zusätzliche Auditappends verändern keine alten Workflowzahlen.
function managerMonthlyCashStorage() {
    const storage = managerNavigationStorage({ pendingCash: false });
    const registry = JSON.parse(storage.rs_profiles_v1);
    const sale = registry.trancheReconciliation.actions[0];
    sale.executedAt = '2026-03-10';
    sale.cashConfirmedAt = '2026-03-10T12:00:00.000Z';
    storage.profile_tagesgeld = '8000';
    storage.profile_cash_history_v1 = JSON.stringify({ version: 1, baselineValue: 9000,
        entries: [{ date: '2026-03-10', value: 10000 }, { date: '2026-04-10', value: 8000 }] });
    Object.assign(registry.profiles['manager-guard'].data, {
        profile_tagesgeld: storage.profile_tagesgeld, profile_cash_history_v1: storage.profile_cash_history_v1
    });
    storage.rs_profiles_v1 = JSON.stringify(registry);
    return storage;
}

/** Schließen mit ungespeicherten Eingaben fragt nach; Verwerfen schreibt nichts. @param {import('playwright').Page} page @param {string} message */
async function discardSaleFlow(page, message) {
    // Der Subpage-Start schreibt updatedAt entprellt; er gehört vor die Bytebaseline.
    await page.evaluate(async () => (await import('./app/shared/persistence-facade.js')).flush());
    const before = (await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value;
    await page.locator('#saleFlowDialog [data-close-dialog-close]').click();
    await page.locator('#navigationGuardDialog[open]').waitFor();
    assert((await page.locator('#navigationGuardDescription').textContent()).includes('verloren'), message);
    await page.locator('#navigationGuardLeave').click();
    await page.locator('#saleFlowDialog').waitFor({ state: 'detached' });
    assert((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value === before, 'Verwerfen des Verkaufs schreibt nichts');
}

/** FR-79: geführter Verkauf ohne Planbezug bis zur Abrechnung. @param {import('playwright').Page} page */
async function openSaleSettlement(page) {
    await page.locator('#depotOpenSaleEntryBtn').click();
    await page.locator('#saleFlowDialog [data-sale-flow-memo]').waitFor();
    await page.locator('#saleFlowDialog [data-sale-flow-primary]').click();
    await page.locator('#saleFlowDialog [data-sale-flow-form]').waitFor();
}

/** FR-79: Abrechnung 1 Stück × 97 € − 2 € Gebühren − 0 € Steuern mit Ordernummer, Gutschrift „Kommt noch“. @param {import('playwright').Page} page */
async function enterBrowserSale(page) {
    await openSaleSettlement(page);
    const field = name => page.locator(`#saleFlowDialog [data-sale-flow-form] [data-sale-flow-field="${name}"]`);
    await page.locator('#saleFlowDialog [data-sale-flow-form] input[type="date"]').fill('2026-07-14');
    for (const [name, value] of [['shares', '1'], ['price', '97'], ['fees', '2'], ['taxes', '0']]) { await field(name).fill(value); await field(name).blur(); }
    await page.locator('#saleFlowDialog [data-sale-flow-form] details summary').click();
    await page.locator('#saleFlowDialog [data-sale-flow-form] details input').fill('browser-order-1');
    await page.locator('#saleFlowDialog [data-sale-flow-primary]').click();
    await page.locator('#saleFlowDialog [data-sale-flow-credit]').waitFor();
}

async function runManagerCashEffectSmoke(browser, baseUrl, changed = false) {
    for (const amount of changed ? ['10100'] : ['8000', '8000,00']) {
        const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', {
            storage: managerMonthlyCashStorage(), fixedTime: '2026-05-10T12:00:00+02:00'
        });
        const { page } = smoke;
        try {
            await page.locator('[data-cash-action="correct"][data-target-action-id="guard-sale"]').waitFor();
            const keys = ['profile_tagesgeld', 'profile_cash_history_v1', 'rs_profiles_v1'];
            const before = await readIndexedDbValues(page, keys);
            await page.locator('[data-cash-action="correct"][data-target-action-id="guard-sale"]').click();
            await page.locator('#cashPostingBalance').fill(amount);
            await page.locator('#cashPostingReason').fill('Synthetische Maibestätigung');
            await page.locator('#cashPostingSubmitBtn').click();
            await page.locator('#cashPostingModal.active').waitFor({ state: 'hidden' });
            const status = await page.locator('#reconciliationStatus').textContent();
            const persistence = await page.locator('#tranchePersistenceStatus').textContent();
            assert(status === (changed
                ? 'Neuer Tagesgeld-Stand übernommen und Korrektur gespeichert. Verkauf und frühere Angaben bleiben unverändert.'
                : 'Korrektur gespeichert, der Kontostand war schon richtig. Verkauf und frühere Angaben bleiben unverändert.'), amount + ': sichtbare Statusmeldung entspricht tatsächlicher Cashwirkung');
            assert(persistence === (changed
                ? 'Neuer Tagesgeld-Stand und Bestätigung dauerhaft gespeichert.'
                : 'Bestätigung dauerhaft gespeichert.'), amount + ': sichtbare Persistenzmeldung entspricht tatsächlicher Cashwirkung');
            const after = await readIndexedDbValues(page, keys);
            const actions = JSON.parse(after.rs_profiles_v1).trancheReconciliation.actions;
            assert(actions.length === 2 && JSON.stringify(actions[0]) === JSON.stringify(JSON.parse(before.rs_profiles_v1).trancheReconciliation.actions[0]), 'Genau ein Auditappend, Verkauf unverändert');
            assert(actions[1].cashBalanceAfterPostingEur === Number(amount.replace(',', '.')), 'Audit dokumentiert explizite Eingabe');
            if (changed) {
                const history = JSON.parse(after.profile_cash_history_v1);
                assert(after.profile_tagesgeld === '10100' && history.entries.length === 3
                    && JSON.stringify(history.entries.at(-1)) === JSON.stringify({ date: '2026-05-10', value: 10100 }), 'Neuer absoluter Stand und genau ein datierter Mai-Cashbeleg');
                assert(JSON.stringify(history.entries.slice(0, 2)) === JSON.stringify(JSON.parse(before.profile_cash_history_v1).entries), 'Frühere Cashbelege unverändert');
            } else {
                assert(after.profile_tagesgeld === before.profile_tagesgeld, 'Auditappend erhält Tagesgeldrohbytes');
                assert(after.profile_cash_history_v1 === before.profile_cash_history_v1, 'Auditappend erhält Cashhistorienrohbytes');
                assert(!/Tagesgeld|übernommen|Cashhistorie/.test(status + persistence), 'Reiner Nachweis meldet keine Cashänderung');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runManagerCashSourceRejectionSmoke(browser, baseUrl) {
    for (const [cashRaw, historyRaw] of [['kaputt', null], ['8000', 'kaputt'], ['8000', 'null'],
        ['8000', JSON.stringify({ version: 1, baselineValue: 9000, entries: [{ date: '2026-04-10', value: 7999 }] })]]) {
        const storage = managerMonthlyCashStorage();
        const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', {
            storage, fixedTime: '2026-05-10T12:00:00+02:00'
        });
        const { page } = smoke;
        try {
            await page.locator('[data-cash-action="correct"][data-target-action-id="guard-sale"]').waitFor();
            await page.evaluate(async ({ cashRaw, historyRaw }) => {
                const { PersistenceFacade, persistenceStorage } = await import('./app/shared/persistence-facade.js');
                persistenceStorage.setItem('profile_tagesgeld', cashRaw);
                if (historyRaw === null) persistenceStorage.removeItem('profile_cash_history_v1');
                else persistenceStorage.setItem('profile_cash_history_v1', historyRaw);
                await PersistenceFacade.flush();
            }, { cashRaw, historyRaw });
            const keys = ['profile_tagesgeld', 'profile_cash_history_v1', 'rs_profiles_v1', 'depot_tranchen'];
            const before = await readIndexedDbValues(page, keys);
            await page.locator('[data-cash-action="correct"][data-target-action-id="guard-sale"]').click();
            assert(await page.locator('#cashPostingFormError').isVisible(), 'Fachlicher Fehler bereits beim Öffnen sichtbar');
            assert(await page.locator('#cashPostingSubmitBtn').isDisabled(), 'Fehler sperrt Submit');
            await page.locator('#cashPostingBalance').fill('10100');
            await page.locator('#cashPostingReason').fill('Synthetischer verweigerter Auftrag');
            await page.locator('#cashPostingForm').evaluate(form => form.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true })));
            const error = await page.locator('#cashPostingFormError').textContent();
            assert(error.includes('Tagesgeldquelle ist beschädigt oder widersprüchlich') && !/Retry ist möglich|Wiederherstellung|wiederhergestellt/.test(error), 'Fachliche Quelle ohne technische Retry-/Rollbackbehauptung');
            assert(await page.locator('#cashPostingSubmitBtn').isDisabled(), 'Neurender über Eingabelistener erhält Submit-Sperre');
            assert(await page.locator('#retryCashPostingSaveBtn').isHidden(), 'Kein technischer Retry');
            assert(await page.evaluate(async () => {
                const { getManagerCashPostingDiagnostics } = await import('./app/tranches/tranchen-manager-page.js');
                return getManagerCashPostingDiagnostics().pendingCashPosting === null;
            }), 'Kein ausstehender Cashauftrag');
            assert(JSON.stringify(await readIndexedDbValues(page, keys)) === JSON.stringify(before), 'Quellenablehnung erhält Backend einschließlich Registry/Audit bytegleich');
            await page.locator('#cashPostingCancelBtn').click();
            await page.locator('#navigationGuardDialog[open]').waitFor();
            await page.locator('#navigationGuardLeave').click();
            await page.locator('#cashPostingModal.active').waitFor({ state: 'hidden' });
            assert(await page.locator('#profileTagesgeld').isEnabled(), 'Profilfeld nach bestätigtem Abbruch bedienbar');
            assert(await page.locator('#depotAddTrancheBtn').isEnabled(), 'Weiterer Managerknopf nach Abbruch bedienbar');
            await page.evaluate(async ({ cashRaw, historyRaw }) => {
                const { PersistenceFacade, persistenceStorage } = await import('./app/shared/persistence-facade.js');
                persistenceStorage.setItem('profile_tagesgeld', cashRaw);
                persistenceStorage.setItem('profile_cash_history_v1', historyRaw);
                await PersistenceFacade.flush();
            }, { cashRaw: storage.profile_tagesgeld, historyRaw: storage.profile_cash_history_v1 });
            await page.locator('[data-cash-action="correct"][data-target-action-id="guard-sale"]').click();
            assert(await page.locator('#cashPostingFormError').isHidden(), 'Gültiges Wiederöffnen löscht Quellenfehler');
            assert(await page.locator('#cashPostingSubmitBtn').isEnabled(), 'Gültiges Wiederöffnen erlaubt Submit');
            await page.locator('#cashPostingCancelBtn').click();
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runNavigationGuardManagerCommits(browser, baseUrl) {
    for (const kind of ['tranche', 'cash-confirm', 'cash-correct']) for (const failure of [false, true]) {
        const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', {
            storage: managerNavigationStorage({ pendingCash: kind !== 'cash-correct' })
        });
        try {
            const { page } = smoke;
            await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
            await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
            await page.locator('.tranche-row').waitFor();
            await page.evaluate(async () => { const { PersistenceFacade } = await import('./app/shared/persistence-facade.js'); await PersistenceFacade.flush(); });
            const before = (await readIndexedDb(page, 'kv', 'depot_tranchen')).value;
            const registryBefore = (await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value;
            await installTauriCloseProbe(smoke);
            await page.evaluate(async () => {
                const { PersistenceFacade } = await import('./app/shared/persistence-facade.js');
                const original = PersistenceFacade.flush;
                const probe = window.__managerWriteProbe = { calls: [], original };
                PersistenceFacade.flush = async (...args) => {
                    const outcome = await new Promise((resolve, reject) => probe.calls.push({ resolve, reject }));
                    if (outcome === false) return false;
                    return original(...args);
                };
            });
            const tranche = kind === 'tranche', modal = page.locator(tranche ? '#trancheModal' : '#cashPostingModal');
            if (tranche) {
                await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
                await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
                await page.locator('[data-action="edit-tranche"]').click(); await page.locator('#trancheDetailsToggle').click(); await page.locator('#name').fill('Synthetische Änderung');
                await page.locator('#trancheForm button[type="submit"]').click();
            } else {
                await page.locator(`[data-cash-action="${kind === 'cash-correct' ? 'correct' : 'confirm'}"]`).click();
                await page.locator('#cashPostingBalance').fill('10120');
                if (kind === 'cash-correct') await page.locator('#cashPostingReason').fill('Synthetische Korrektur');
                await page.locator('#cashPostingSubmitBtn').click();
            }
            await page.waitForFunction(() => window.__managerWriteProbe.calls.length === 1);
            const assertHeld = async () => {
                assert(await page.locator('#profileTagesgeld').isDisabled(), 'Profilautosave-Feld verhindert Nutzereingaben während Managerwrite und Rückschreiben');
                await page.keyboard.press('Escape');
                await page.locator(tranche ? '#closeTrancheModalBtn' : '#cashPostingCancelBtn').evaluate(node => node.click());
                await modal.evaluate(node => node.dispatchEvent(new MouseEvent('click', { bubbles: true })));
                await page.locator('.suite-navigation a[href="Handbuch.html"]').evaluate(node => node.click());
                await page.evaluate(() => window.__tauriCloseProbe.request());
                await waitForTauriCloseSettled(page);
                await page.evaluate(() => window.__tauriCloseProbe.advance(4000));
                assert(await modal.isVisible(), 'Langer echter Managerwrite erhält Fachdialog bei Escape/Knopf/Overlay');
                assert(page.url().endsWith('/depot-tranchen-manager.html'), 'Programmatischer Rahmenlink überholt keinen Managerwrite');
                assert(await page.locator('#navigationGuardDialog').isHidden(), 'Commit zeigt keine Verwerfzustimmung');
                assert(await page.evaluate(() => window.__tauriCloseProbe.closes) === 0, 'Übernommener EXE-Versuch bleibt auch nach drei Sekunden offen');
                assert(await page.evaluate(() => window.__tauriCloseProbe.replies.some(reply => reply.response === 'hold')),
                    'EXE-Doppel belegt tatsächliche Übernahme durch Facade');
            };
            await assertHeld();
            await page.evaluate(failure => window.__managerWriteProbe.calls[0].resolve(!failure), failure);
            if (failure) {
                // Seit Paket 11 schreibt die Cashbestätigung Tagesgeld und Audit in einem Transaktionsflush; der gehaltene
                // Flush ist dort die Vorabsicherung vor jedem Write. Scheitert sie, gibt es nichts zurückzuschreiben.
                if (tranche) {
                    await page.waitForFunction(() => window.__managerWriteProbe.calls.length === 2);
                    await assertHeld();
                    await page.evaluate(() => window.__managerWriteProbe.calls[1].resolve(true));
                }
                const retry = page.locator(tranche ? '#retryTrancheDialogSaveBtn' : '#retryCashPostingSaveBtn');
                await retry.waitFor({ state: 'visible' });
                await initializeBrowserSmokeNavigationGuard(page);
                await page.waitForFunction(() => {
                    return !window.__browserSmokeNavigationGuard.reasons().some(reason => reason.phase === 'commit');
                });
                assert((await readIndexedDb(page, 'kv', 'depot_tranchen')).value === before, 'Rückschreibflush bestätigt exakte Tranchenbytes');
                assert((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value === registryBefore, 'Rückschreibflush bestätigt exakte Registrybytes');
                assert(await modal.isVisible(), 'Fehler ersetzt keine Baseline und schließt keinen Editor');
                const error = page.locator(tranche ? '#trancheFormError' : '#cashPostingFormError');
                assert(await error.isVisible() && /bestätigt|gespeichert|Speicher|Persistenz|Rückschreiben/i.test(await error.textContent()),
                    'Tatsächlicher Speicherfehler steht im sichtbaren Fachdialog');
                await retry.click();
                const retryCall = tranche ? 2 : 1;
                await page.waitForFunction(index => window.__managerWriteProbe.calls.length === index + 1, retryCall);
                await page.evaluate(index => window.__managerWriteProbe.calls[index].resolve(true), retryCall);
            }
            await modal.waitFor({ state: 'hidden' });
            await page.waitForFunction(() => !document.getElementById('profileTagesgeld').disabled);
            assert(await page.locator('#profileTagesgeld').isEnabled(), 'Profilautosave-Feld ist nach bestätigtem Managerende wieder bedienbar');
            await page.evaluate(async () => { const { PersistenceFacade } = await import('./app/shared/persistence-facade.js'); PersistenceFacade.flush = window.__managerWriteProbe.original; });
            await page.evaluate(() => window.__tauriCloseProbe.request());
            await waitForTauriCloseSettled(page);
            assert(await page.evaluate(() => window.__tauriCloseProbe.closes) === 1, 'Nach bestätigtem Managerende schließt ein neuer Versuch genau einmal');
            if (!tranche) {
                const registry = JSON.parse((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value);
                assert(registry.trancheReconciliation.actions.length === 2, 'Cashretry hängt dieselbe Action-ID genau einmal an');
                const record = registry.trancheReconciliation.actions[1];
                assert(record.cashBalanceAfterPostingEur === 10120 && record.targetActionId === 'guard-sale'
                    && record.actionId === (kind === 'cash-correct' ? 'cash-correction:v1:guard-sale:1' : 'cash-confirmation:v1:guard-sale'),
                    'Dialogretry bestätigt ursprünglichen Cashstand und kanonische Action-ID');
            } else {
                const lots = JSON.parse((await readIndexedDb(page, 'kv', 'depot_tranchen')).value);
                assert(lots.length === JSON.parse(before).length && lots[0].trancheId === JSON.parse(before)[0].trancheId
                    && lots[0].name === 'Synthetische Änderung', 'Dialogretry bestätigt ursprüngliche Tranche mit stabiler ID');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runNavigationGuardManagerDirtyInputs(browser, baseUrl) {
    await runNavigationGuardModal(browser, baseUrl);
    const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', { storage: managerNavigationStorage({ pendingCash: false }) });
    try {
        const { page } = smoke;
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.locator('[data-action="edit-tranche"]').click();
        await page.locator('#trancheDetailsToggle').click();
        const dirty = () => page.evaluate(async () => {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            return getPageNavigationGuard().reasons().some(reason => reason.owner === 'manager-dialog-tranche' && reason.dirty);
        });
        assert(!await dirty(), 'Befülltes Editformular startet sauber');
        await page.locator('#taxExempt').check(); assert(await dirty(), 'Checkbox gehört zur echten Dialogbaseline');
        await page.locator('#taxExempt').uncheck(); assert(!await dirty(), 'Checkbox-Rückänderung ist sauber');
        // Ohne Datum bleibt der Bestand von Hand wählbar.
        const date = await page.locator('#purchaseDate').inputValue();
        await page.locator('#purchaseDate').fill('');
        const type = await page.locator('#type').inputValue();
        await page.locator(`#trancheTypeChoices [data-tranche-type="${type === 'aktien_neu' ? 'aktien_alt' : 'aktien_neu'}"]`).click();
        assert(await page.locator('#type').inputValue() !== type && await dirty(), 'Select gehört zur echten Dialogbaseline');
        await page.locator(`#trancheTypeChoices [data-tranche-type="${type}"]`).click();
        await page.locator('#purchaseDate').fill(date);
        assert(await page.locator('#type').inputValue() === type && !await dirty(), 'Select-Rückänderung ist sauber');
        await page.locator('#dismissTrancheModalBtn').click();
        await page.locator('[data-cash-action="correct"]').click();
        const balance = await page.locator('#cashPostingBalance').inputValue();
        await page.locator('#cashPostingBalance').fill('10120'); await page.locator('#cashPostingReason').fill('Nicht gespeichert');
        await page.locator('#cashPostingCancelBtn').click(); await page.locator('#navigationGuardDialog[open]').waitFor();
        await page.keyboard.press('Escape');
        await waitForNavigationDecisionSettled(page);
        assert(await page.locator('#cashPostingModal').isVisible(), 'Escape im obersten Schutzdialog erhält Casheditor');
        assert(await page.locator('#cashPostingReason').inputValue() === 'Nicht gespeichert', 'Cash-Bleiben erhält Verlustwerte');
        assert(await page.evaluate(() => document.activeElement.id) === 'cashPostingCancelBtn', 'Cash-Bleiben stellt Fokusauslöser wieder her');
        await page.locator('#cashPostingBalance').fill(balance); await page.locator('#cashPostingReason').fill('');
        await page.locator('#cashPostingCancelBtn').click(); await page.locator('#cashPostingModal').waitFor({ state: 'hidden' });
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

async function runNavigationGuardManagerPricePreparation(browser, baseUrl) {
    const lots = Array.from({ length: 6 }, (_, index) => createBrowserTranche({ trancheId: `guard-${index}`, ticker: `TEST${index}.DE` }));
    const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', { storage: managerNavigationStorage({ lots }) });
    try {
        const { page } = smoke;
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.locator('.tranche-row').first().waitFor();
        const before = (await readIndexedDb(page, 'kv', 'depot_tranchen')).value;
        await page.evaluate(() => {
            const original = window.fetch;
            window.__managerQuotes = [];
            window.fetch = (url, options) => String(url).startsWith('http://127.0.0.1:8787')
                ? new Promise(resolve => window.__managerQuotes.push({ url: String(url), resolve })) : original(url, options);
        });
        await page.locator('#managerQuoteRefresh').click(); await page.waitForFunction(() => window.__managerQuotes.length === 12); // KF-1: je .DE-Ticker Xetra, Stuttgart, Düsseldorf, München
        assert(await page.locator('#profileTagesgeld').isDisabled(), 'Profilautosave-Feld verhindert Nutzereingaben bereits während der Kursvorbereitung');
        const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
        await link.click(); await page.locator('#navigationGuardDialog[open]').waitFor();
        await page.locator('#navigationGuardStay').click();
        await waitForNavigationDecisionSettled(page);
        assert(await page.evaluate(() => window.__managerQuotes.length) === 12, 'Bleiben erhält den laufenden Batch');
        assert(await page.locator('#profileTagesgeld').isDisabled(), 'Bleiben gibt das Profilfeld bei weiterlaufendem Kursbatch nicht frei');
        await link.click(); await page.locator('#navigationGuardLeave').click();
        await initializeBrowserSmokeNavigationGuard(page);
        await page.waitForFunction(() => window.__browserSmokeNavigationGuard.reasons().some(reason => reason.phase === 'cancelling'));
        assert(page.url().endsWith('/depot-tranchen-manager.html'), 'Angenommene Kurskündigung wartet Jobenden vor Navigation');
        await page.evaluate(() => window.__managerQuotes[0].resolve(new Response('{}', { status: 404 })));
        assert(page.url().endsWith('/depot-tranchen-manager.html'), 'Ein Jobende reicht nicht für Navigation');
        await page.evaluate(() => { for (const [index, request] of window.__managerQuotes.entries()) if (index) request.resolve(new Response(JSON.stringify({ symbol: new URL(request.url).searchParams.get('symbol'), price: 150, currency: 'EUR', asOf: Math.floor(Date.now() / 1000) }))); });
        await page.waitForURL('**/Handbuch.html');
        assert((await readIndexedDb(page, 'kv', 'depot_tranchen')).value === before, 'Späte Quotes starten nach Kündigung keine Persistenz');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

// Ausschließlich Browser-Testadapter: hält die echte Replace-/Readback-/Rollbackkette.
async function installHistoryAdapterBarrier(context, { stage = 'write' } = {}) {
    await context.addInitScript(({ stage }) => {
        window.__historyWriteProbe = { stage, entered: false, held: false, written: false, failed: false, release: null };
    }, { stage });
    await context.route('**/app/shared/persistence-adapter-indexeddb.js', async route => {
        const response = await route.fetch();
        const source = await response.text();
        const writeAnchor = 'async replaceLiveRecords(records, options = {}) {';
        const readAnchor = 'async loadAll() {';
        assert(source.includes(writeAnchor) && source.includes(readAnchor), 'Browserbarriere findet reale IndexedDB-Adaptermethoden');
        const pause = `probe.held = true; probe.entered = true; await new Promise(resolve => { probe.release = resolve; });`;
        const body = source.replace(writeAnchor, `${writeAnchor}
            const probe = window.__historyWriteProbe;
            const state = JSON.parse(records.ruhestandsmodellValues_v29_guardrails || '{}');
            const target = state.wealthHistory?.entries?.some(entry => entry.id === 'annual:2026');
            if (!probe.held && (target && probe.stage === 'write' || probe.failed && probe.stage === 'rollback')) { ${pause} }
            if (target) probe.written = true;`)
            .replace(readAnchor, `${readAnchor}
            const probe = window.__historyWriteProbe;
            if (probe.written && probe.stage === 'readback' && !probe.held) { ${pause} }`);
        await route.fulfill({ response, body });
    });
}

async function runNavigationGuardAnnualFinalization(browser, baseUrl) {
    const smoke = await createAnnualNavigationProbe(browser, baseUrl, { adapterStage: 'readback' });
    try {
        const { page } = smoke;
        await startBalanceAnnual(page); await page.waitForFunction(() => window.__historyWriteProbe.entered);
        const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
        await activateLinkBehindAnnualDialog(link);
        assert(page.url().endsWith('/index.html'), 'Finaler Jahresreadback sperrt App-Enter');
        const state = JSON.parse((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value);
        assert(state.wealthHistory.entries.some(entry => entry.id === 'annual:2026'), 'Adapterbarriere erreicht echten finalen Jahreswrite');
        await installTauriCloseProbe(smoke);
        await page.evaluate(() => window.__tauriCloseProbe.request()); await waitForTauriCloseSettled(page);
        await page.evaluate(() => window.__tauriCloseProbe.advance(4000));
        assert(await page.evaluate(() => window.__tauriCloseProbe.closes) === 0, 'Übernommenes EXE-Schließen bleibt im finalen Jahresreadback über drei Sekunden gesperrt');
        assert(await page.evaluate(() => window.__tauriCloseProbe.replies.map(reply => reply.response).join(',')) === 'hold,reject', 'Echte Facade übernimmt und verweigert Schluss im finalen Jahreswrite');
        assert(await page.locator('#suiteNavigationStatus').textContent() === 'Jahresabschluss schreibt – bitte warten', 'Finaler Jahreswrite erhält ortsfesten EXE-Wartehinweis');
        await page.evaluate(() => window.__historyWriteProbe.release());
        await waitForPageCondition(page, async () => !(await import('./app/shared/navigation-guard-dialog.js')).getPageNavigationGuard(document, window).isBusy());
        assert(await page.evaluate(() => window.__tauriCloseProbe.closes) === 0, 'Jahresende startet keinen automatischen EXE-Schluss');
        await closeAnnualResult(page);
        await link.focus(); await page.keyboard.press('Enter'); await page.waitForURL('**/Handbuch.html');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
    for (const accept of [false, true]) {
        const smoke = await createAnnualNavigationProbe(browser, baseUrl, { adapterStage: 'write' });
        try {
            const { page } = smoke;
            await startBalanceAnnual(page); await page.waitForFunction(() => window.__historyWriteProbe.entered);
            const pending = (await readBalanceBrowserState(page)).annualPeriodMetadata.pendingCommit;
            await nativeNavigationAttempt(page, { kind: 'navigate', accept, target: `${baseUrl}/Handbuch.html`, verify: async () => {
                assert(JSON.parse((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value).annualPeriodMetadata.pendingCommit.snapshotId === pending.snapshotId,
                    'Native Entscheidung im finalen Adapterwrite erhält bestätigten Jahres-Recoverymarker');
                if (!accept) {
                    await page.evaluate(() => window.__historyWriteProbe.release());
                    await waitForPageCondition(page, async () => !(await import('./app/shared/navigation-guard-dialog.js')).getPageNavigationGuard(document, window).isBusy());
                    assert(!(await readBalanceBrowserState(page)).annualPeriodMetadata.pendingCommit, 'Nach nativer Ablehnung beendet echte Jahresfinalisierung ihren Marker');
                }
            } });
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function createAnnualNavigationProbe(browser, baseUrl, { preparing = false, failFinalize = false, adapterStage = null } = {}) {
    const smoke = await createPage(browser, 'Navigation guard annual', {
        storage: withClosingYearExpenseEvidence(createBalanceStorage(2026), 2026), annualFixtures: { targetYear: 2026 },
        observeWealthUpdates: true, fixedTime: '2027-01-15T12:00:00+01:00'
    });
    if (adapterStage) await installHistoryAdapterBarrier(smoke.context, { stage: adapterStage });
    await smoke.context.addInitScript(({ preparing, failFinalize }) => {
        window.__annualNavigationProbe = { preparing, failFinalize, entered: false, release: null };
    }, { preparing, failFinalize });
    await smoke.context.route('**/app/shared/annual-coordinator.js', async route => {
        const response = await route.fetch();
        const body = (await response.text()).replace(
            'validateLiveState = () => ({ ok: true }),',
            `validateLiveState = async () => {
                const probe = window.__annualNavigationProbe;
                if (probe.preparing) {
                    probe.entered = true;
                    await new Promise(resolve => { probe.release = resolve; });
                }
                return { ok: true };
            },`
        );
        await route.fulfill({ response, body });
    });
    await smoke.page.goto(`${baseUrl}/index.html`);
    await smoke.page.locator('[data-overview-annual]').waitFor();
    await waitForWealthBrowserIdle(smoke.page);
    if (!preparing && !adapterStage) await smoke.page.evaluate(async () => {
        const { PersistenceFacade } = await import('./app/shared/persistence-facade.js');
        const original = PersistenceFacade.replaceRecordsTransactional;
        PersistenceFacade.replaceRecordsTransactional = async function(records, ...args) {
            const candidate = JSON.parse(records.ruhestandsmodellValues_v29_guardrails || '{}');
            if (candidate.annualPeriodMetadata?.lastCommittedPeriod === 'calendar-year:2026'
                && candidate.wealthHistory?.entries?.some(entry => entry.id === 'annual:2026')) {
                const probe = window.__annualNavigationProbe;
                // Die Sonde hält genau den Jahreswrite. Der folgende Monatswrite
                // enthält denselben Jahresstand und muss anschließend durchlaufen.
                if (!probe.entered) {
                    probe.entered = true;
                    await new Promise(resolve => { probe.release = resolve; });
                    if (probe.failFinalize) throw new Error('SYNTHETIC_ANNUAL_FINALIZATION');
                }
            }
            return original.call(this, records, ...args);
        };
    });
    return smoke;
}

