        const before = (await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value;
        await openSimulatorProfileList(page);
        assert(await page.locator('#simProfileList input').count() === 0, 'Annahmen haben keine Haushaltscheckboxen');
        assert((await page.locator('#simProfileList').textContent()).includes('Synthetisch A, Synthetisch B'), 'Annahmen zeigen beide Haushaltspersonen');
        assert((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value === before, 'Öffnen der Annahmen schreibt keine Mitgliedschaft');
        smoke.assertNoErrors();
