            await page.locator('.data-heading a[href="Handbuch.html#daten-sicherung"]').click();
            await page.waitForURL('**/Handbuch.html#daten-sicherung');
            await waitForPageCondition(page, () => document.activeElement?.id === 'daten-sicherung');
            assert(await page.locator('.toc-link[href="#daten-sicherung"]').count() === 1, 'Handbuchanker hat eindeutigen TOC-Eintrag');
            await page.locator('.toc-link[href="#daten-sicherung"]').click();
            assert(new URL(page.url()).hash === '#daten-sicherung', 'Handbuchnavigation erhält teilbaren Hash');
            await page.goto(`${baseUrl}/index.html#fullBackupImportBtn`); await page.waitForURL('**/Daten-Sicherung.html#fullBackupImportBtn');
            await waitForPageCondition(page, () => document.activeElement?.id === 'fullBackupImportBtn');
            await page.goto(`${baseUrl}/Balance.html`); await waitBalanceHouseholdList(page);
            assert(await page.locator('#snapshot-management').count() === 0, 'Balance enthält keine Sicherungskarte');
            // AK-1: Alt+E und Alt+I springen nicht mehr nach Daten & Sicherung.
            await waitForPageCondition(page, async () => (await import('./app/shared/navigation-guard-dialog.js')).getPageNavigationGuard().reasons().length === 0);
            await page.keyboard.press('Alt+e'); await page.keyboard.press('Alt+i'); await page.waitForTimeout(300);
            assert(new URL(page.url()).pathname.endsWith('/Balance.html'), 'Alt+E und Alt+I bleiben in der Balance');

            await page.goto(`${baseUrl}/Daten-Sicherung.html`);
            await page.locator('#dataPriceCheck').scrollIntoViewIfNeeded();
            assert(await page.locator('#dataPriceCheck').isVisible(), 'Alter Technikzugang öffnet Kursdienst');
            assert(await page.locator('a[href="index.html#probelaufControls"]').count() === 0, 'Sicherungskarte hat keinen zusätzlichen Startlink');
            await page.locator('.suite-header #probelaufStart').click();
            await page.locator('[data-probelauf-dialog]').waitFor({ state: 'visible' });
            await page.keyboard.press('Escape');
            await page.goto(`${baseUrl}/index.html#probelaufControls`);
            await page.locator('[data-probelauf-dialog]').waitFor({ state: 'visible' });
            assert(await page.locator('[data-probelauf-dialog]').count() === 1, 'Initialer Altanker öffnet genau den gemeinsamen Dialog');
            await page.keyboard.press('Escape');
            await page.locator('[data-probelauf-dialog]').waitFor({ state: 'hidden' });
            await page.evaluate(() => { location.hash = ''; });
            await waitForPageCondition(page, () => location.hash === '');
            await page.evaluate(() => { location.hash = 'probelaufControls'; });
            await page.locator('[data-probelauf-dialog]').waitFor({ state: 'visible' });
            assert(await page.locator('[data-probelauf-dialog]').count() === 1, 'Späterer Altanker öffnet den gemeinsamen Dialog einmal');
