// Inhaltsvergleich gespeicherter Records: verschachtelte JSON-Strings werden gelesen, Schlüssel sortiert,
// reine Speicherzeitstempel (meta.updatedAt) ignoriert.
function semanticRecord(raw) {
    const norm = value => {
        if (typeof value === 'string' && /^[\[{]/.test(value)) { try { return norm(JSON.parse(value)); } catch { return value; } }
        if (Array.isArray(value)) return value.map(norm);
        if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map(key => [key, norm(value[key])]));
        return value;
    };
    const strip = value => {
        if (Array.isArray(value)) return value.map(strip);
        if (value && typeof value === 'object') { const copy = {}; for (const [k, v] of Object.entries(value)) copy[k] = k === 'meta' && v && typeof v === 'object' ? Object.fromEntries(Object.entries(strip(v)).filter(([mk]) => mk !== 'updatedAt')) : strip(v); return copy; }
        return value;
    };
    return raw == null ? raw : JSON.stringify(strip(norm(raw)));
}

