// AU1c: heutiger Startseitenanschluss, ein Hauptklick, synthetische Daten.
async function runAnnualCombinedClose(browser, baseUrl, source) {
    // Beide alten Einstiege landen auf der Übersicht. Nur der Fehlerfall braucht
    // zwei Varianten: Abbruch und Ausnahme nach dem bestätigten Archivwrite.
    for (const failureName of source === 'attempt' ? ['AbortError', 'Error'] : [null]) {
        const records = createMusterHaushaltRecords('2026-12-15');
        if (source === 'copy' || source === 'prepoint' || source === 'attempt') {
            const registry = JSON.parse(records.rs_profiles_v1);
            const strip = data => {
                const state = JSON.parse(data[BALANCE_STATE_KEY]);
                for (const key of ['annualPeriodMetadata', 'ageAdjustedForInflation', 'lastInflationAppliedAtYear', 'needsAdjustedForInflationYear', 'annualMarketDataMeta']) delete state[key];
                delete state.lastState.lastInflationAppliedAtAge; state.lastState.cumulativeInflationFactor = 1;
                state.wealthHistory = { schemaVersion: 1, entries: [] };
                data[BALANCE_STATE_KEY] = JSON.stringify(state); delete data.annual_plan_record_v1;
            };
            strip(records); Object.values(registry.profiles).forEach(profile => strip(profile.data));
            records.rs_profiles_v1 = JSON.stringify(registry);
        }
        const smoke = await openSmokePage(browser, baseUrl, 'index.html?probelauf=1', {
            storage: records, fixedTime: '2026-12-15T12:00:00+01:00', observeWealthUpdates: true,
            quoteFixtures: { default: { price: 100, asOf: Date.parse('2026-12-15T00:00:00Z') / 1000 } }
        });
        const page = smoke.page;
        try {
            await waitForPageCondition(page, key => ['complete', 'empty'].includes(JSON.parse(sessionStorage.getItem(key) || 'null')?.status), STARTUP_PRICE_SESSION_KEY);
            await page.locator('#probelaufStart').click();
            let trial = page.locator('[data-probelauf-dialog]');
            await trial.locator(`[data-probelauf-source="${['prepoint', 'attempt'].includes(source) ? 'copy' : source === 'demo' ? 'max-erika' : source}"]`).click();
            await trial.getByLabel('Spielkurse', { exact: true }).check();
            await trial.getByLabel('Testdatum').fill('2026-12-14');
            await waitForProbelaufReload(page, () => trial.getByRole('button', { name: 'Spielbereich starten', exact: true }).click(), '2026-12-14');
            await page.locator('#probelaufBandText').filter({ hasText: '14.12.2026', hasNotText: /wird gestartet|Wiederherstellung/ }).waitFor();
            await page.locator('#probelaufBand [data-probelauf-action="date"]').click();
            trial = page.locator('[data-probelauf-dialog]');
            await trial.getByLabel('Testdatum').fill('2027-01-02');
            await waitForProbelaufReload(page, () => trial.getByRole('button', { name: 'Datum übernehmen', exact: true }).click(), '2027-01-02');
            await page.locator('#probelaufBandText').filter({ hasText: '02.01.2027', hasNotText: /wird umgestellt|Wiederherstellung/ }).waitFor();
            await page.goto(`${baseUrl}/index.html`); await waitForWealthBrowserIdle(page);
            const read = () => page.evaluate(async () => (await import('./app/shared/persistence-facade.js')).PersistenceFacade.readPersistedRecords());
            if (source === 'demo') await page.evaluate(async () => {
                const { PersistenceFacade: P } = await import('./app/shared/persistence-facade.js');
                const { DAILY_PRICES_KEY, emptyHistorySymbol, historyDay } = await import('./app/tranches/tranchen-history-store.js');
                const days = ['2025-12-31', '2026-06-15', '2026-12-31'].map(historyDay);
                await P.replaceRecordsTransactional({ [DAILY_PRICES_KEY]: JSON.stringify({ version: 1, symbols: { 'VWCE.DE': {
                    ...emptyHistorySymbol(), currency: 'EUR', days, closes: [100, 1000, 125], queried: [[days[0], days[2]]]
                } } }) }, { probelaufDomainWrite: true, allowKey: key => key === DAILY_PRICES_KEY });
            });
            if (source === 'attempt') {
                // Produktiver Jahreseinstieg; Fehler erst nach tatsächlichem
                // Archivwrite und bytegleichem Readback, vor dem Metadatenstart.
                await page.evaluate(async failureName => {
                    const { SnapshotArchive: A } = await import('./app/shared/snapshot-archive.js');
                    const create = A.createSnapshot;
                    window.__annualArchiveProbe = { calls: 0, confirmed: false };
                    A.createSnapshot = async (...args) => {
                        window.__annualArchiveProbe.calls++;
                        const point = await create(...args), saved = await A.readSnapshot(point.id);
                        if (JSON.stringify(saved) !== JSON.stringify(point)) throw new Error('SYNTHETIC_SNAPSHOT_READBACK_MISMATCH');
                        window.__annualArchiveProbe.confirmed = true;
                        A.createSnapshot = create;
                        const error = new Error('SYNTHETIC_AFTER_CONFIRMED_ANNUAL_SNAPSHOT');
                        error.name = failureName;
                        throw error;
                    };
                    const controls = (await import('./app/overview/overview-annual-close.js')).getOverviewAnnualClose(document);
                    const start = controls.start;
                    controls.start = async (...args) => {
                        const result = await start(...args);
                        window.__annualArchiveProbe.status = result.status;
                        window.__annualArchiveProbe.error = result.error?.message;
                        window.__annualArchiveProbe.finished = true;
                        return result;
                    };
                }, failureName);
                await openOverviewAnnual(page);
                const root = page.locator('#balanceAnnualClose'); await root.waitFor({ state: 'visible' });
                await assertCloseDialogFrame(page);
                await root.locator('[data-close-dialog-activate="expenses"]').click();
                await root.locator('[data-overview-example="all"]').click();
                await page.locator('[data-expenses-preview-accept]').click();
                await page.locator('#expensesImportPreview').waitFor({ state: 'detached' });
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                const before = await read(), pointsBefore = await readIndexedDb(page, 'snapshots', null);
                await root.getByRole('button', { name: 'Jahr 2026 abschließen', exact: true }).click();
                await page.waitForFunction(() => window.__annualArchiveProbe.finished);
                const attempt = await page.evaluate(() => {
                    const { calls, confirmed, status, error } = window.__annualArchiveProbe; return { calls, confirmed, status, error }; });
                assert(attempt.confirmed && attempt.calls === 1 && attempt.status === (failureName === 'AbortError' ? 'cancelled' : 'invalid')
                    && attempt.error === 'SYNTHETIC_AFTER_CONFIRMED_ANNUAL_SNAPSHOT', 'Ein echter bestätigter Vorabpunkt endet mit ursprünglichem Abbruch/Fehler');
                const saved = await read(), state = JSON.parse(saved[BALANCE_STATE_KEY]);
                assert(JSON.stringify(saved) === JSON.stringify(before) && !state.annualPeriodMetadata && !saved.annual_plan_record_v1,
                    'Vorabpunkt ohne Metadatenstart verändert keine Finanzbytes und bestätigt keinen Erfolg');
                assert(state.lastState.cumulativeInflationFactor === 1, 'Abgebrochener Jahresversuch verändert keine Inflation');
                assert(await readIndexedDb(page, 'snapshots', null) === pointsBefore + 1, 'Genau ein neuer Jahresvorabpunkt');
                await root.locator('[data-close-dialog-close]').click();
                const beforeQuote = await read();
                await page.evaluate(async () => {
                    const { PersistenceFacade: P } = await import('./app/shared/persistence-facade.js');
                    const records = await P.readPersistedRecords(), registry = JSON.parse(records.rs_profiles_v1), lots = JSON.parse(records.depot_tranchen);
                    lots[0].currentPrice += 1; const raw = JSON.stringify(lots);
                    registry.profiles[records.rs_current_profile].data.depot_tranchen = raw;
                    await P.replaceRecordsTransactional({ depot_tranchen: raw, rs_profiles_v1: JSON.stringify(registry) },
                        { probelaufDomainWrite: true, allowKey: key => ['depot_tranchen', 'rs_profiles_v1'].includes(key) });
                });
                const archiveBytes = () => page.evaluate(async () => {
                    const { SnapshotArchive: A } = await import('./app/shared/snapshot-archive.js');
                    return JSON.stringify(await Promise.all((await A.listSnapshots()).sort((a, b) => a.id.localeCompare(b.id)).map(point => A.readSnapshot(point.id))));
                });
                const afterQuote = await read(), snapshots = await archiveBytes();
                assert(afterQuote.depot_tranchen !== beforeQuote.depot_tranchen && afterQuote.rs_profiles_v1 !== beforeQuote.rs_profiles_v1,
                    'Bestätigter Folge-Kurswrite verändert Tranchen und Registry auf derselben Seite');
                await page.evaluate(() => document.dispatchEvent(new Event('overview-backup-changed')));
                // JW-1a (Fable P2-2): Nach dem metadatenlosen Vorabpunkt des Erstabschlusses bleibt der Abschluss trotz Kurswrite offen.
                await page.locator('[data-overview-annual]').filter({ hasText: 'Abschluss starten' }).waitFor();
                assert(await page.locator('#pageDialog[open]').count() === 0, 'Reines Rendern öffnet kein Klärungspopup');
                assert(JSON.stringify(await read()) === JSON.stringify(afterQuote) && await archiveBytes() === snapshots,
                    'Anzeigeaktualisierung erhält Finanz- und Archivbytes');
                assert(await page.evaluate(() => window.__annualArchiveProbe.calls) === 1, 'Kein weiterer Jahresversuch nach dem Folgewrite');
                smoke.assertNoErrors(); continue;
            }
            if (source === 'copy') assert(!JSON.parse((await read())[BALANCE_STATE_KEY]).annualPeriodMetadata, 'Synthetischer Kopiebestand hat tatsächlich keinen Periodenvermerk');
            if (source === 'prepoint') {
                // Echter markerloser Vorabstand im Archiv; der nächste Startkurslauf
                // aktualisiert Live-Tranchen und Registry nach seiner Archivierung.
                await page.evaluate(async () => {
                    const { PersistenceFacade: P } = await import('./app/shared/persistence-facade.js');
                    const { SnapshotArchive: A } = await import('./app/shared/snapshot-archive.js');
                    const { appNow } = await import('./app/shared/app-clock.js');
                    const live = await P.readPersistedRecords(), registry = JSON.parse(live.rs_profiles_v1);
                    const tranches = JSON.parse(live.depot_tranchen);
                    tranches.forEach(lot => { lot.currentPrice = 1; lot.asOf = Math.floor(Date.parse('2026-12-15T00:00:00Z') / 1000); });
                    const raw = JSON.stringify(tranches);
                    registry.profiles[live.rs_current_profile].data.depot_tranchen = raw;
                    await P.replaceRecordsTransactional({ depot_tranchen: raw, rs_profiles_v1: JSON.stringify(registry) },
                        { probelaufDomainWrite: true, allowKey: key => ['depot_tranchen', 'rs_profiles_v1'].includes(key) });
                    const records = await P.readPersistedRecords();
                    // JW-1a (Fable P2-2): Nur ein Vorabpunkt mit Jahresmetadaten, die live fehlen, verlangt noch eine Klärung.
                    const { CONFIG } = await import('./app/balance/balance-config.js');
                    const pointRecords = A.captureCurrentRecords({ keys: Object.keys(records), getItem: key => records[key] });
                    pointRecords[CONFIG.STORAGE.LS_KEY] = JSON.stringify({ ...JSON.parse(pointRecords[CONFIG.STORAGE.LS_KEY]),
                        annualPeriodMetadata: { schemaVersion: 1, lastCommittedPeriod: 'calendar-year:2025', pendingCommit: null } });
                    await A.createSnapshot({ id: 'browser-isolated-before', label: 'Synthetischer Jahresvorabstand',
                        createdAt: appNow().toISOString(), activeProfileId: records.rs_current_profile,
                        kind: 'annual-close-pre-mutation',
                        restoreScope: { profileRegistryMode: 'replace-all-rollback', profileLiveDataMode: 'replace-all-rollback', liveKeyMode: 'snapshot-full' },
                        records: pointRecords });
                });
                await page.evaluate(async key => {
                    const { areaSessionStorage } = await import('./app/shared/persistence-area-storage.js');
                    areaSessionStorage(sessionStorage).removeItem(key);
                }, STARTUP_PRICE_SESSION_KEY);
                await page.reload(); await waitForWealthBrowserIdle(page);
                await waitForPageCondition(page, async () => {
                    const { readStartupPriceReport, waitStartupPriceRefresh } = await import('./app/tranches/tranchen-startup-prices.js');
                    await (await import('./app/overview/overview-main.js')).initOverview(document, window);
                    await waitStartupPriceRefresh(document);
                    return readStartupPriceReport()?.status === 'complete';
                });
                const changed = await page.evaluate(async () => {
                    const { PersistenceFacade: P } = await import('./app/shared/persistence-facade.js');
                    const { SnapshotArchive: A } = await import('./app/shared/snapshot-archive.js');
                    const records = await P.readPersistedRecords(), point = await A.readSnapshot('browser-isolated-before');
                    const { CONFIG } = await import('./app/balance/balance-config.js');
                    const state = JSON.parse(records[CONFIG.STORAGE.LS_KEY]);
                    return { quoteChanged: records.depot_tranchen !== point.records.depot_tranchen,
                        registryChanged: records.rs_profiles_v1 !== point.records.rs_profiles_v1,
                        unmarked: !state.annualPeriodMetadata && !state.needsAdjustedForInflationYear && !state.lastInflationAppliedAtYear
                            && !state.annualMarketDataMeta && !records.annual_plan_record_v1 };
                });
                assert(changed.quoteChanged && changed.registryChanged, 'Startkurswrite nach Vorabpunkt verändert echte Tranchen- und Registryrecords');
                assert(changed.unmarked, 'Vorabpunktfall bleibt ohne Periodenmetadaten, Zieljahresmarker und Abschlussbeleg');
                await page.locator('[data-overview-annual]').filter({ hasText: 'Jahresstatus klären' }).waitFor();
                assert((await page.locator('#overviewFocus').textContent()).includes('Jahresstatus'), 'Übersicht zeigt Klärungsanlass vor dem Jahresknopf');
                assert(await page.locator('#pageDialog[open]').count() === 0, 'Initiale Archivlesung öffnet kein Popup');
                const beforeClarification = await read(), pointsBefore = await readIndexedDb(page, 'snapshots', null);
                const clickAnnual = () => openOverviewAnnual(page);
                await clickAnnual();
                await page.locator('#pageDialog[open]').waitFor();
                await page.locator('[data-page-dialog-cancel]').click();
                await waitForWealthBrowserIdle(page);
                assert(JSON.stringify(await read()) === JSON.stringify(beforeClarification), 'Klärungsabbruch erhält alle Finanzrecords');
                assert(await readIndexedDb(page, 'snapshots', null) === pointsBefore, 'Klärungsabbruch erzeugt keinen Punkt');
                assert(await page.locator('#balanceAnnualClose[open]').count() === 0, 'Klärungsabbruch öffnet keine Vorbereitung');
                await clickAnnual();
                await page.locator('[data-page-dialog-input]').selectOption('not_committed');
                await page.locator('[data-page-dialog-accept]').click();
            } else {
                await openOverviewAnnual(page);
            }
            const root = page.locator('#balanceAnnualClose'); await root.waitFor({ state: 'visible' });
                await assertCloseDialogFrame(page);
            assert(await page.locator('#pageDialog[open]').count() === 0, 'Kein pauschales Jahresperioden-Popup');
            const before = await read();
            await root.locator('[data-close-dialog-activate="expenses"]').click();
            await root.locator('[data-overview-example="all"]').click();
            await page.locator('#expensesImportPreview').waitFor();
            await page.locator('[data-expenses-preview-accept]').click();
            await page.locator('#expensesImportPreview').waitFor({ state: 'detached' });
            await waitForPageCondition(page, async old => (await import('./app/shared/persistence-facade.js')).persistenceStorage.getItem('balance_expenses_v1') !== old, before.balance_expenses_v1);
            if (source === 'demo') {
                // HP-2 (JA-4): Ändern bei der ersten Person und „Stand bestätigen“ bei der zweiten blenden Hinweis und Knopf sichtbar aus.
                await root.locator('[data-close-dialog-activate="cash"]').click();
                const [changed, confirmed] = await root.locator('[data-tagesgeld-confirm-person]').evaluateAll(nodes => nodes.map(node => node.dataset.tagesgeldConfirmPerson));
                await root.locator(`input[data-tagesgeld-person="${changed}"]`).fill('20.000');
                await root.locator(`[data-tagesgeld-confirm-person="${confirmed}"]`).click();
                for (const person of [changed, confirmed]) {
                    assert(!await root.locator(`[data-tagesgeld-confirm-hint="${person}"]`).isVisible()
                        && !await root.locator(`[data-tagesgeld-confirm-person="${person}"]`).isVisible(), `HP-2: Hinweis und Knopf „Stand bestätigen“ verschwinden (${person})`);
                }
                // HP-3: Die bestätigte Person zeigt „bestätigt“ in derselben Statuszeile wie „geändert · vorher …“.
                const status = person => root.locator(`input[data-tagesgeld-person="${person}"]`).evaluate(input => document.getElementById(`${input.id}-hint`).textContent);
                const [changedStatus, confirmedStatus] = [await status(changed), await status(confirmed)];
                assert(confirmedStatus.startsWith('bestätigt · Stand vom ') && changedStatus.startsWith('geändert · vorher '),
                    `HP-3: Statuszeilen „bestätigt“ und „geändert“ (${confirmedStatus} | ${changedStatus})`);
            }
            await prepareBrowserClose(page);
            if (source === 'demo') {
                // ATH-1 (FR-89): Das Tageshoch gilt automatisch; der Schritt Marktdaten nennt es mit Datum, eine Wahl gibt es nicht.
                const tab = root.locator('[data-close-dialog-activate="preview"]');
                assert(!(await tab.textContent()).includes('Wahl'), 'ATH-1: Planreiter ohne Wahl');
                await tab.click();
                assert(await root.locator('[data-annual-market-reading]').count() === 0, 'ATH-1: keine Marktwahl');
                await root.locator('[data-close-dialog-activate="market"]').click();
                assert(await root.locator('[data-annual-market-readings]').filter({ hasText: '1.000,00 € · Tagesschluss vom 15.06.2026' }).isVisible(), 'ATH-1: Schritt Marktdaten nennt das Allzeithoch mit Datum');
            }
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            await root.getByRole('button', { name: 'Jahr 2026 abschließen', exact: true }).click();
            await root.locator('[data-annual-combined-result="C"]').waitFor();
            assert(await root.locator('#annualMonthStepConfirm').count() === 0, 'Kein zweiter Überweisungs-Bestätigungsknopf');
            assert((await root.textContent()).includes('Monatsbudget'), 'Kombinierter Beleg zeigt die Budgetzeile');
            const closed = await read();
            if (source === 'demo') {
                const state = JSON.parse(closed[BALANCE_STATE_KEY]);
                assert(state.inputs.ath === 1000 && state.annualMarketDataMeta.ath.lastHighAsOf === '2026-06-15' && !('reading' in state.annualMarketDataMeta.ath), 'ATH-1: Tageshoch mit Datum ohne Wahl im bestätigten Speicher');
                assert(!(await root.textContent()).includes('Wahl im Jahresabschluss'), 'ATH-1: Ergebnis ohne Hochwahl');
            }
            const snapshots = await page.evaluate(async () => {
                const { SnapshotArchive: archive } = await import('./app/shared/snapshot-archive.js');
                return Promise.all((await archive.listSnapshots()).filter(point => point.kind === 'annual-close-pre-mutation' || point.label === 'Monatsabschluss 2026-12').map(point => archive.readSnapshot(point.id)));
            });
            assert(snapshots.length === (source === 'prepoint' ? 3 : 2) && new Set(snapshots.map(point => point.id)).size === snapshots.length, 'Getrennte verifizierte Jahres- und Dezemberpunkte');
            const monthPoint = snapshots.find(point => point.label === 'Monatsabschluss 2026-12');
            assert(JSON.parse(monthPoint.records[BALANCE_STATE_KEY]).annualPeriodMetadata.lastCommittedPeriod === 'calendar-year:2026', 'Monatspunkt enthält den endgültigen Jahresstand');
            assert(closed.profile_tagesgeld === monthPoint.records.profile_tagesgeld, 'Beide Writes verwenden dasselbe bestätigte Tagesgeld');
            if (source === 'prepoint') {
                const state = JSON.parse(closed[BALANCE_STATE_KEY]);
                assert(state.lastState.cumulativeInflationFactor === 1.025, 'Offenklärung wendet synthetische Jahresinflation genau einmal an');
                assert(state.annualPeriodMetadata.lastCommittedPeriod === 'calendar-year:2026', 'Offenklärung finalisiert erst nach vollständiger Vorbereitung das Jahr');
                assert(Object.values(JSON.parse(closed.annual_plan_record_v1).entries).some(receipt => receipt.periodId === 'calendar-year:2026'), 'Endgültiger Jahresplanbeleg ist bestätigt');
                assert(await page.locator('#pageDialog[open]').count() === 0, 'Coordinatorabschluss wiederholt die Offenklärung nicht');
            }
            await root.getByRole('button', { name: 'Fertig', exact: true }).click();
            await page.goto(`${baseUrl}/index.html`); await page.reload(); await waitForWealthBrowserIdle(page);
            assert(await page.locator('[data-overview-month], [data-overview-annual]').count() === 0, 'Startseitenreload hat keinen offenen Dezember oder Jahresabschluss');
            assert((await read()).annual_plan_record_v1 === closed.annual_plan_record_v1, 'Reload und spätere Vorschau erhalten den endgültigen Planbeleg');
            if (source === 'prepoint') {
                const count = await readIndexedDb(page, 'snapshots', null);
                const repeated = await page.evaluate(async () => (await import('./app/overview/overview-annual-close.js')).getOverviewAnnualClose(document).start());
                assert(repeated.status === 'already_committed', 'Erneuter Start nach Reload bleibt idempotent');
                const after = await read();
                assert(after.annual_plan_record_v1 === closed.annual_plan_record_v1 && JSON.parse(after[BALANCE_STATE_KEY]).lastState.cumulativeInflationFactor === 1.025,
                    'Idempotenter Neustart erhält Jahresbeleg und einmalige Inflation');
                assert(await readIndexedDb(page, 'snapshots', null) === count, 'Idempotenter Neustart erzeugt keinen weiteren Punkt');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

// VK-3c (Gutachten VK3B-FABLE P1-1): „Kauf rückgängig“ mit „Tagesgeld zurücksetzen“ hält nach dem Neuladen. Martin und Petra, 23.10.2026:
// Tagesgeld 100.000 € → Kauf 98.930,75 € mit bestätigter Abbuchung → 1.069,25 € → Storno mit Rücksetzen auf 100.000 €. Das alte Feld der
// Seite überschreibt den neuen Stand weder nach dem Kauf noch nach dem Storno.
async function runVk3cCancelBuyCashSmoke(browser, baseUrl) {
    const DATE = '2026-10-23', MARTIN = 'muster_martin';
    const smoke = await openSmokePage(browser, baseUrl, 'depot-tranchen-manager.html', { storage: createMusterHaushaltRecords(DATE, 'martin-petra', 'grund'),
        fixedTime: `${DATE}T12:00:00+02:00`, viewport: { width: 1920, height: 1080 } });
    const { page } = smoke;
    const cash = () => page.evaluate(async id => {
        const { persistenceStorage } = await import('./app/shared/persistence-facade.js');
        return { registry: JSON.parse(persistenceStorage.getItem('rs_profiles_v1')).profiles[id].data.profile_tagesgeld,
            live: persistenceStorage.getItem('profile_tagesgeld'), field: document.getElementById('profileTagesgeld').value,
            history: JSON.parse(persistenceStorage.getItem('profile_cash_history_v1') || '{"entries":[]}').entries.filter(entry => entry.date === '2026-10-23').map(entry => entry.value) };
    }, MARTIN);
    const reloaded = async () => {
        await page.waitForFunction(() => !window.__vk3cDocument && document.getElementById('suiteProfileContext')?.dataset.profileId, null, { timeout: 30000 });
        await waitSuiteIdentity(page, MARTIN);
        await page.locator('#tranchenTable .tranche-row').first().waitFor({ state: 'attached' });
    };
    try {
        await waitSuiteIdentity(page, MARTIN);
        assert((await cash()).registry === '100000', 'Martin vor dem Kauf 100.000 €');
        // Kauf mit bestätigter Abbuchung über den Haushaltsschreiber, danach derselbe Neuladeweg wie nach dem geführten Kauf.
        await page.evaluate(async date => {
            window.__vk3cDocument = true;
            const { prepareSaleFlowWrite, commitSaleFlowWrite } = await import('./app/tranches/household-sale-writer.js');
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            const { PersistenceFacade } = await import('./app/shared/persistence-facade.js');
            const tranche = { schemaVersion: 2, trancheId: 'vk3c_buy', name: 'Muster Aktien-ETF', type: 'aktien_neu', category: 'equity', ticker: 'VWCE.DE',
                isin: 'IE00BK5BQT80', shares: 685, purchasePrice: 98930.75 / 685, currentPrice: 144.46978, purchaseDate: date, tqf: 0.3, taxExempt: false, notes: '' };
            await commitSaleFlowWrite(await prepareSaleFlowWrite({ buys: [{ profileId: 'muster_martin', actionId: 'vk3c-buy', executedAt: date, assetClass: 'equity',
                tranche, shares: 685, gross: 98920.85, fees: 9.9, cashValue: 1069.25 }] }));
            void getPageNavigationGuard(document).reload({ flush: () => PersistenceFacade.flush(), reload: () => location.reload() });
        }, DATE);
        await reloaded();
        let after = await cash();
        assert(after.registry === '1069.25' && after.live === '1069.25' && after.field === '1.069,25', `nach dem Kauf bleibt 1.069,25 € stehen: ${JSON.stringify(after)}`);
        // Storno über die Tabelle: „Tagesgeld zurücksetzen“, Vorschlag 100.000,00 € bestätigen.
        await page.locator('#tranchenTable [data-asset-group]').evaluateAll(groups => groups.forEach(group => { group.open = true; }));
        await page.evaluate(() => { window.__vk3cDocument = true; });
        await openTrancheDetailDelete(page, 'vk3c_buy'); await page.locator('#deleteTrancheDialogBtn').click();
        const choiceDialog = page.locator('#pageChoiceDialog');
        await choiceDialog.waitFor({ state: 'visible' });
        const choice = await choiceDialog.textContent();
        assert(/Tagesgeld zurücksetzen \(Vorschlag 100\.000\s€\)/.test(choice), `Wahl mit Vorschlag: ${choice}`);
        await choiceDialog.locator('[data-page-choice-accept]').click();
        const field = page.locator('#pageDialog[open] [data-page-dialog-input]');
        await field.waitFor();
        assert(await field.inputValue() === '100.000', 'Eingabefeld mit Vorschlag (VN-4 Nachtrag 1: Tagesgeld in ganzen Euro)');
        await page.locator('#pageDialog[open] [data-page-dialog-accept]').click();
        await reloaded();
        after = await cash();
        assert(after.registry === '100000' && after.live === '100000' && after.field === '100.000', `nach dem Storno bleibt 100.000 € stehen: ${JSON.stringify(after)}`);
        assert(!after.history.includes(1069.25), `Tagesgeldverlauf ohne 1.069,25 € am 23.10.: ${JSON.stringify(after.history)}`);
        const stored = JSON.parse((await readIndexedDb(page, 'kv', 'rs_profiles_v1')).value).profiles[MARTIN].data.profile_tagesgeld;
        assert(stored === '100000', 'dauerhaft gespeichert: 100.000 €');
        assert(!/Profilwerte dauerhaft gespeichert/.test(await page.locator('#tranchePersistenceStatus').textContent()), 'keine Sicherung des alten Feldes');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}

// VK-3d: Spielbereich mit Beispielhaushalt und Testdatum wie im Bedien-Durchlauf (Start auf der Startseite, danach die Zielseite).
async function openVk3dPlayArea(browser, baseUrl, source, date, entry, variant = null) {
    const smoke = await openSmokePage(browser, baseUrl, 'index.html', { storage: createMusterHaushaltRecords('2026-11-01'),
        fixedTime: '2026-11-13T12:00:00+01:00', viewport: { width: 1920, height: 1080 } });
    const page = smoke.page;
    await waitForPageCondition(page, key => ['complete', 'empty'].includes(JSON.parse(sessionStorage.getItem(key) || 'null')?.status), STARTUP_PRICE_SESSION_KEY);
    await page.locator('#probelaufStart').click();
    const dialog = page.locator('[data-probelauf-dialog]');
    await dialog.locator(`[data-probelauf-source="${source}"]`).click();
    if (variant) await dialog.locator(`[data-muster-variant="${variant}"]`).click();
    await dialog.getByLabel('Spielkurse', { exact: true }).check();
    await dialog.getByLabel('Testdatum').fill(date);
    await waitForProbelaufReload(page, () => dialog.getByRole('button', { name: 'Spielbereich starten', exact: true }).click(), date);
    await page.goto(`${baseUrl}/${entry}`, { waitUntil: 'load' });
    return smoke;
}

