        await monthly.fill('1.500');
        await monthly.press('Tab');
        await page.locator('#managerPartnershipStatus').filter({ hasText: /^Gespeichert$/ }).waitFor();
        const rule = JSON.parse(await raw()).testament.muster_werner;
